local addon = WoWKoreanClient
if not addon.active then return end
local rows = addon.quests
rows[29843]={title={{17,1956273092},"린 윈드퍼 이모"},description={{355,1885924541},"다들 정리되는 대로 마을로 돌아갈 거예요. 이제 아무도 저를 못 건드려요! 머리를 뻥 차 버릴 거예요! 이만하면 혼나지도 않겠죠.$B$B정말 고마워요. 판다 마을에 있는 린 이모에게 우리가 무사하고 돌아가는 중이라고 전해 주실래요? 이모가 멋진 옛날 물건을 잔뜩 가지고 있어서 보상으로 주실지도 몰라요."},objectives={{37,1363619882},"판다 마을에서 바람털 린과 이야기하십시오."}}
rows[29844]={completion={{123,1167163326},"우리 트롤들은 어떤 종족들이 존재해 온 것보다 더 오랫동안 제국 분열을 겪어왔지. 우리는 언제나 폐허에서 다시 일어섰어."},progress={{42,2082898153},"다 드라카리 역사 명판을 찾았나요?"},title={{13,1422431372},"후손을 위하여"},description={{244,595393788},"얼음 트롤의 대지는 예전의 영광스러운 모습이라곤 찾아볼 수 없다네.$B$B용기가 있다면 군드락 안으로 들어가 드라카리 제국이 어쩌다 이런 종말을 맞게 되었는지 알 수 있는 단서를 찾아다 주게나.$B$B언젠가 후손 얼음 트롤들에게 우리 땅을 돌려주게 될 테니까 말이네."},objectives={{67,893568968},"군드락에 있는 톨마르가 드라카리 역사 서판 6개를 가져다 달라고 부탁했습니다."}}
rows[29845]={title={{33,1192805761},"궁지에 몰린 상인들"},description={"If King Wrynn thinks that the attack on the Bravery is an isolated incident, he's mistaken.$B$BLook around the harbor and you'll see all the angry merchants who can't get their goods or money to Kalimdor. Perhaps the king will listen to their voices if he won't heed mine alone.$B$BGo talk to them, $n. Hear their grievances and gather their petitions before you return to Stormwind Keep.","혹시라도 린 국왕님께서 용기호에 대한 공격이 개별적인 사건이라고 생각하신다면, 정말 큰 실수입니다.$B$B여기 항구를 돌아보면, 칼림도어로 상품이나 돈을 가져가지 못해 발을 동동 구르고 있는 상인들을 잔뜩 만날 수 있을 겁니다. 제 말만으로는 충분하지 않다면, 다른 상인들의 목소리까지 국왕님께 전해 주십시오.$B$B가서 다른 상인들의 이야기도 들어 보십시오, $N 님. 그들의 고충에 귀를 기울이고, 탄원서를 모아 스톰윈드 왕궁으로 돌아가시는 게 좋겠습니다."},objectives={{83,1222321910},"스톰윈드 항구에 있는 화난 상인들과 대화하고, 상인의 탄원서 7장을 모아야 합니다."}}
rows[29846]={title={{34,1400606090},"대장 루퍼스 하드윅"},description={{448,343875452},"길니아스 출신인 루퍼스 하드윅 대장이 이번 일에 딱 맞을 거예요.$B$B늘상 그랬던 것처럼 이번 작전을 통해 얻을 수 있는 전리품만 이야기해도 그를 작전에 참여시킬 수 있겠지만, 사실 대장의 마음을 사로잡으려면 조금 더 섬세한 부분까지 챙겨줘야 해요.$B$B연금술 가게로 가서 희석한 운향귤 유황과 층층나무 추출물, 진정용 샴푸를 사세요. 이 물건들을 가지고 대장을 찾아가시되, 그를 부끄럽게 할 말은 하지 마세요.$B$B얼라이언스 함선들의 운명이 당신에게 달려 있어요."},objectives={{150,1949029006},"마법사 지구의 연금술 가게에서 희석한 운향귤 유황, 층층나무 추출물, 진정용 샴푸를 구입한 다음 대장 루퍼스 하드윅과 대화해야 합니다."}}
rows[29847]={completion={{43,118669254},"그럼, 저와 함께 하시겠다는 말씀이시죠? 좋습니다. 아주 좋습니다."},title={{16,320244811},"도둑을 잡으려면"},description={{292,492783691},"이 동굴을 지나면 바로 라벤홀트 장원입니다. 아무한테도 들키지 않고 몰래 숨어들어 가셔야 합니다!$B$B<당신에게 모종의 마법을 거는 모스트라즈>$B$B자… 이제 제가 당신을 지켜볼 수 있습니다. 장원을 조사하시는 동안 의사소통도 할 수 있고요. 이제 안으로 잠입해서 알을 찾아내십시오. 붙잡히지 마시고요…"},objectives={{68,624544650},"라벤홀트 장원에 잠입해, 잃어버린 검은용 알을 찾아내야 합니다."}}
rows[29848]={completion={{197,1685791160},"<칼디르는 잠시 동안 말없이 수정구를 응시했다.>$B$B슬픔의 소녀만큼 진실한 슬픔을 느낀 존재는 없었습니다.$B$B로켄에 맞서 싸우는 우리의 노력을 계속하는 동안 그녀의 정신을 기억합시다.$B"},progress={{85,1129175771},"다른 방법이 있었으면 좋겠지만, 이제 소녀에게는 죽음만이 유일한 구원인 것 같군요."},title={{19,549142730},"쓸쓸한 순찰대원"},description={{278,2139909960},"저는 창조주분들이나 그 피조물에게 제 목숨을 기꺼이 바칠 것입니다.$B$B그러나 로켄의 배신으로 온 울두아르가 세상에 반기를 든 것 같군요. 특히 고뇌의 마녀가 새로운 명령을 받고 괴로움에 빠져 동요하는 것 같습니다.$B$B고뇌의 마녀에게 저세상의 안식을 주고, 그녀의 눈물 한 방울을 제게 가져다주십시오."},objectives={{125,1104109961},"돌의 전당에 있는 칼디르 아이언베인이 고뇌의 마녀를 처치하고 고뇌의 눈물 수정을 가져다 달라고 부탁했습니다."}}
rows[29849]={title={{30,389848879},"함포잡이 블라스트배럴"},description={{337,1572130906},"이번 작전에 필요한 두 번째 함선의 선장은 대포 조작의 일인자인 드워프, 아르단 블라스트배럴이에요. 바다 위에서 호드 함선을 날려버리는 데에는 아르단과 그의 선원들을 따를 이가 없지요.$B$B아이언포지의 군사 지구에서 블라스트배럴을 찾아보세요. 그와 대화하여 선원들과 함께 이번 임무에 참여할 수 있는지 확인해 주세요."},objectives={{120,776258190},"아이언포지로 가서 아르단 블라스트배럴과 대화하고, 그를 도와 아이언포지에서 선원 6명을 모아야 합니다."}}
rows[29850]={completion={"Well done, $R.$B$BEvery weapon we can take away from Loken is a great boon to our own war effort.","잘했어, $R.$B$B. 로켄에게서 빼앗을 수 있는 모든 무기는 우리 전쟁 노력에 큰 도움이 될 거야."},title={{18,659427183},"부패한 구조물"},description={{239,603092632},"무쇠 드워프들이 거대한 석조 구조물을 조각하느라 분주히 움직이고 있습니다. 저는 그 구조물이 곧 강력한 무기로 사용될까봐 두렵군요.$B$B너무 늦기 전에 당신이 그들의 감독관인 크리스탈루스와 벌써부터 걸어 돌아다니기 시작하는 암흑룬 거인을 처치해 주십시오!"},objectives={{94,1050082933},"돌의 전당에 있는 칼디르 아이언베인이 암흑룬 거인 7명과 크리스탈루스를 처치해달라고 부탁했습니다."}}
rows[29851]={completion={"I am honored to stand in the presence of such a fierce warrior.$B$BYou have brought honor to yourself and to your people, $n!","이처럼 용맹한 전사 앞에 서게 되어 영광입니다. 당신은 당신 자신과 당신의 민족에게 영광을 안겨주셨습니다!"},title={{26,1772286234},"최고의 용사"},description={"With this tournament we grow ever closer to our final confrontation with the Lich King.$B$B$n, fight with valor and honor. Every fighter here has gathered for the common good.$B$BTogether, we will stop Arthas!","우리는 이 시합으로 리치 왕과 벌일 최후의 전투에 그 어느 때보다도 가까이 다가섰네.$B$B$N, 용기와 명예를 가지고 싸우게나. 이곳에 모인 전사들은 모두 같은 목적이 있다네.$B$B우리는, 모두 힘을 합쳐 아서스를 저지할 걸세!"},objectives={{89,860258116},"대영주 티리온 폴드링이 당신에게 용사의 시험장을 완료하라는 명령을 내렸습니다."}}
rows[29852]={title={{36,1581763758},"\"빠른손\"이라 불린 사나이"},description={{367,215503906},"이번 작전에 끌어들여야 할 세 번째 용병선은, 무시무시한 근접 전투 솜씨로 악명 높은 ≪빠른손≫ 서튼의 배에요. 블라스트배럴은 함포를 사랑하지만, 서튼 함장은 근접 전투를 선호하죠.$B$B아마 스톰윈드 항구에서 일거리를 찾아 어슬렁거리고 있을 거예요. 조심하세요. 작전에 참여하기 전에, 당신에게 뭔가 일거리를 줄 테니까요."},objectives={{99,33601674},"대장 ≪빠른손≫ 서튼과 대화한 후, 일등항해사 윌리엄스를 처치하고 서튼을 작전에 참가시켜야 합니다."}}
rows[29853]={title={{20,96671053},"최고의 용사"},description={"With this tournament we grow ever closer to our final confrontation with the Lich King.$B$B$n, you are to represent the Alliance in this grand arena.$B$BProve yourself against Azeroth's finest. Go forward with honor.","우리는 이 시합으로 리치 왕과 벌일 최후의 전투에 그 어느 때보다도 가까이 다가섰네.$B$B$N, 자네는 이 웅장한 투기장에서 얼라이언스의 표상이 되어야 하네.$B$B자네가 아제로스 최고의 용사라는 것을 알게 해주게나. 명예롭게 싸우게."},objectives={{82,1697735217},"국왕 바리안 린이 당신에게 용사의 시험장을 완료하라는 명령을 내렸습니다."}}
rows[29854]={title={{29,1941275666},"칼림도어 점령"},description={"Victory shall soon be ours! Our forces have engaged the enemy all over Kalimdor.$B$BWarchief Garrosh Hellscream has commanded all able-bodied $rs to report for duty in support of our latest offensive.$B$BMake your way to Grommash Hold in Orgrimmar and present yourself to General Nazgrim for immediate assignment! For the Horde!","승리는 곧 우리 차지가 될 것이다! 우리 병력이 칼림도어 전역에서 적과 전투를 벌이고 있다.$B$B가로쉬 헬스크림 대족장님의 명을 받들어, 신체 건강한 $R|1은;는; 모두 이번 공격 작전에 참가하라.$B$B오그리마의 그롬마쉬 요새로 출두하여 나즈그림 장군에게 보고하고 즉시 임무를 받아야 한다! 호드를 위하여!"},objectives={{56,1994103629},"오그리마의 그롬마쉬 요새에 있는 장군 나즈그림에게 보고해야 합니다."}}
rows[29856]={title={{13,420560529},"뼈의 돌제단"},description={{270,1892608947},"정신이 맑아졌습니다.$B$B집중력도 향상된 느낌입니다.$B$B주위에 있는 곤충들이 웅웅거리는 소리에 잠이 들었던 모양입니다. 틀림 없이 그랬을 겁니다!$B$B주변을 둘러보니, 북쪽에 또 다른 바위 제단이 보입니다.$B$B그쪽은 조금 더 조용할지도 모릅니다…"},objectives={{47,786895738},"뼈의 돌제단에서 명상용 초를 사용해야 합니다."}}
rows[29857]={title={{34,1483008036},"함선은 어디에?"},description={{402,1487860434},"우리 함대는 대부분 테라모어 공격에 참여하고 있기 때문에, 기타 지역에서 적과 교전을 하고 칼림도어를 완전히 봉쇄하려면 함선이 더 필요하오.$B$B대족장님께서 잿빛 골짜기의 조람가르 전초기지에 있는 조선공들에게 무슨 수를 써서든 요청한 숫자대로 함선을 만들어 내라고 친히 명령하셨는데, 아직도 새 배는 도착하지 않고 있소.$B$B그곳으로 직접 찾아가서 감독관들에게 무슨 일인지 확인해 보시오. 대족장님께서 배를 내놓으라고 하신다는 말을 전해 줘야 하오!"},objectives={{116,1101956170},"잿빛 골짜기의 조람가르 전초기지에 있는 감독관 목스와 대화하고, 마을 밖의 배에 있는 나이트 엘프 공격대원 6명을 처치해야 합니다."}}
rows[29858]={title={{18,159588084},"세월의 지혜"},description={{347,1978340690},"이방인이여, 인생의 시련에 겸손하고 열린 마음으로 대처하는 법을 배워야 합니다.$B$B회의론자의 편협하고 의심이 가득한 눈초리를 통해서는 지혜를 받아들일 수 없습니다.$B$B바위의 돌제단에서 저를 찾으십시오. 고대의 명상술을 알려드리겠습니다.$B$B마음의 평화를 찾고 나면, 당신이 구하는 답이 생각보다 가까이에 있음을 알게 될 겁니다."},objectives={{69,1641677384},"바위의 돌제단에서 전승지기 초와 대화하고 명상해야 합니다."}}
rows[29859]={title={{30,1347739753},"첩보원은 이 안에 있다"},description={"This is unacceptable! The warchief needs every ship he can get to secure Kalimdor!$B$BHow DID the night elves find out about the new fleet in time to destroy it? There's only one way...$B$BOrgrimmar is full of the enemy's eyes and ears, $n, and it is our job to root them out. Belloc Brightblade has provided me with a tool that he says can help reveal the spies.$B$BUse it, but don't trust it alone. Use your judgment.","용납할 수 없소! 칼림도어를 봉쇄하려면 대족장님께서는 최후의 배 한 척까지 모두 동원해야 하오!$B$B대체 나이트 엘프들이 어떻게 우리 함대에 대해 알아내고 파괴할 수 있었단 말이오? 아마 방법은 하나 뿐일 것이오…$B$B오그리마는 적의 눈과 귀로 가득 차 있소, $N. 그리고 그걸 뿌리뽑는 것이 바로 우리가 할 일이오. 벨록 브라이트블레이드가 첩보원을 찾아낼 수 있는 장비를 가져왔소.$B$B그걸 사용하시오. 하지만 장비에 의존해서는 안 되오. 최후의 판단은 당신 몫이오."},objectives={{75,138138720},"수상한 시민을 심문하여 나이트 엘프 첩보원 6명의 정체를 밝히고 제거해야 합니다."}}
rows[29860]={completion={"Volkhan shall haunt the dreams of my people no more.$B$BContinue your efforts, little $R. In time, I am certain my people will grow to forgive Thorim.","볼칸은 더 이상 내 백성의 꿈을 괴롭히지 않을 것이다. $B$B계속 노력하거라, 꼬마 $R. 시간이 지나면 내 백성은 토림을 용서하게 될 거라고 확신한다."},title={{21,733716513},"완전히 정반대"},description={"I shall speak plainly to you, little $r. My people have not been the same since our ties with Thorim were severed.$b$bVolkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.","단도직입적으로 말하마, 작은 $R|1이여;여;. 토림과 관계가 끊어진 이후로 우리 종족은 예전과 같지 않다.$B$B볼칸은 우리나 자신, 둘 중 하나가 없어지기 전에는 멈추지 않을 것이다. 우리는 평화를 바라지만, 안타깝게도 전쟁밖에 선택이 없는 것 같구나."},objectives={{74,48906110},"번개의 전당에 있는 폭풍전령 엘리린이 볼칸을 처치해 달라고 했습니다."}}
rows[29861]={completion={"That vile worm is dead?$B$BYou have turned out to be a great boon to my people, little $R.$B$BPlease accept this gift in return for your loyal friendship.","그 끔찍한 벌레가 죽었단 말인가? 꼬마 R아, 자네는 우리 백성에게 큰 축복이 되었네. 자네의 변함없는 우정에 대한 보답으로 이 선물을 받아주겠네."},progress={{34,1302738618},"로켄에게 정의가 실현되었습니까?"},title={{18,1292604852},"무슨 일이 있어도!"},description={{155,945652637},"어떤 식으로든, 로켄은 쓰러질 것이다.$B$B그놈을 처치하는 명예와 영광은 모두 네 차지이다.$B$B거짓만 뱉어내는 그놈을 처치하고 파편을 가져오면, 내 너에게 영원히 감사할 것이다."},objectives={{139,1104535963},"번개의 전당에 있는 폭풍전령 엘리린이 로켄을 처치하고 로켄의 파편을 가져와 달라고 했습니다."}}
rows[29862]={completion={{92,947069923},"우리 외에는 거의 아무도 알지 못하겠지만, 당신은 오늘 세상을 구한 것이 분명합니다."},title={{16,649042019},"길 뚫기"},description={{212,696025322},"로켄의 군대는 전쟁을 준비하고 있다. 하지만 자신들이 선공을 당할 수도 있다는 건 전혀 생각하지 못했을 터.$B$B바로 지금이 놈들을 칠 때이다. 장군 비야른그림과 그의 군대를 쳐부숴라. 놈들이 아제로스의 모든 생명을 위협하기 전에 말이다!"},objectives={{135,239182060},"번개의 전당에 있는 폭풍전령 엘리린이 폭풍으로 벼려낸 치유사 3명, 폭풍으로 벼려낸 전술가 3명, 장군 비야른그림을 처치해 달라고 했습니다."}}
rows[29863]={completion={{49,583216661},"우리가 행동할 시간은 얼마 남지 않았다. 로켄은 전쟁을 준비한다."},title={{19,1449992890},"폭풍전령 엘리린"},description={{215,1355255943},"로켄과의 전투를 위해 번개의 전당에 전령을 파견했다.$B$B로켄의 엄청난 군대를 생각할 때, 당연히 그에겐 도움의 손길이 필요하리라. 배신자 로켄을 처단할 수 있도록 엘리린에게 힘을 빌려다오."},objectives={{89,1962837190},"제왕 요쿰이 번개의 전당으로 가서 폭풍전령 엘리린과 이야기해 달라고 했습니다."}}
rows[29864]={completion={{76,1845353698},"우리가 재앙의 손아귀에서 막아내는 모든 병사는 한 생명 이상의 가치를 지닙니다. 감사합니다."},title={{21,713979892},"지원자 차단"},description={{297,1967306197},"우리는 스컬지 전쟁 기계에 희생되는 사람을 최대한 줄이려고 노력하고 있어요.$B$B그런데 이 지역의 브리쿨은 자발적으로 리치 왕의 휘하에 들어가, 우리의 이런 노력에 찬물을 끼얹고 있답니다.$B$B용감한 투사여, 그대가 브리쿨의 영적인 지도자인 스발라를 물리쳐 주셔야 합니다. 스발라가 자기 동족을 영원한 어둠 속으로 끌고 들어가기 전에요!"},objectives={{63,271638133},"은빛 고해사제 페일트리스가 스발라 소로우그레이브를 처치해 달라고 했습니다."}}
rows[29865]={completion={{83,1332344905},"정말 고귀한 영웅이시군요. 당신은 젊고 덜 잘생겼던 제 모습을 떠올리게 합니다."},title={{17,1482222839},"비단숲 길"},description={{378,328702999},"여기서 서쪽으로 가면 비단숲 길이 있습니다. 아쉽게도 그곳의 거미들이 사악하고 끈적끈적한 점액질을 내뿜기 시작하는 바람에 끔찍한 곳이 되어 버렸지만…$B$B제가 직접 그 끔찍한 괴물들과 맞서고 싶지만, 누군가 여기 국수 가게를… 음… 위험한 일이라든가 뭐 그런 것으로부터 지켜야 하지 않겠습니까.$B$B영웅이여, 가서 그 괴물들을 정복하십시오! 만약 성공한다면 제가 소싯적의 제 영웅담을 기꺼이 들려드리겠습니다.$B$B물론 적절한 보상도 드릴 거고요."},objectives={{27,453136914},"비단숲 거미 8마리를 처치해야 합니다."}}
rows[29866]={completion={{148,954586865},"정말 고마워요! 완벽해요!$b$b제 것처럼 달라붙지 않았으면 좋겠네요.$b$b지금 당장 시라를 찾아서 이걸 전해줘야겠어요!"},progress={{26,246850234},"실크우드를 찾으셨나요?"},title={{22,164945962},"끈끈한 실가닥"},description={{291,1625741694},"아, 여행자님, 잘 오셨어요. 저 좀 도와주실 수 있으신가요?$B$B제 연인 시라 골든드래프트가 비단을 구하고 있어요. 저는 개인적으로 비단을 싫어해요. 항상 제 털에 들러붙거든요.$B$B하지만 그녀에게 감동을 주고 싶어요.$B$B서쪽의 비단숲에서 비단을 좀 가져다 주시면, 기꺼이 대가를 치를게요."},objectives={{31,1743085368},"온전한 비단 실가닥 10개를 모아야 합니다."}}
rows[29867]={title={{34,271090679},"어둠사냥꾼 우르코진"},description={{498,2136515433},"나이트 엘프들이 우리 대도시에 첩보원들을 다시 배치하기 전에, 함대 봉쇄선의 빈 자리를 어서 채워야 하오.$B$B검은창 부족은 지금까지는 이번 전쟁에 크게 관여하지 않았지만, 어둠사냥꾼 우르코진과 그의 병력들을 설득하여 함대에 참여시킬 수만 있다면, 상황도 많이 바뀔 것이오.$B$B그런데 문제는, 우르코진이 정령의 축복 없이는 전쟁에 뛰어들지 않으려 한다는 것이오. 메아리 섬의 검은창 요새에서 항해의 토템을 회수해서, 정기의 골짜기에 있는 우르코진에게 가져다 주시오."},objectives={{142,1889840318},"메아리 섬의 검은창 요새에 있는 항해의 토템을 회수한 후, 오그리마, 정기의 골짜기에 있는 어둠사냥꾼 우르코진에게 가져가야 합니다."}}
rows[29868]={title={{29,330163626},"대장 카테론"},description={{442,1826409103},"칼림도어 봉쇄선을 강화하기 위해 함선이 더 필요하오. 그리고 이 일에 꼭 맞는 블러드 엘프가 하나 있지.$B$B바로 카테론 대장이오. 그의 선원들은 호드 중에서 해상전에 대한 경험이 가장 풍부한 것으로 유명하오. 하지만 문제는, 카테론과 선원들은 모든 일거리에 대한 보수를 선불로 받는다오.$B$B북부 불모의 땅에 있는 톱니항에 돈을 가지고 가시오. 그리고 카테론 대장과 선원들이 돈을 얼마나 받아야 움직일지, 또 성과급은 얼마를 요구할지 알아보시오."},objectives={{128,848732500},"북부 불모의 땅, 톱니항에서 대장 카테론과 대화하고, 착수금으로 100골드를 제시해야 합니다."}}
rows[29869]={title={{17,479374780},"한 손으로 박수 치기"},description={{379,1700529448},"아직 배워야 할 게 많습니다. 하지만 이제 당신의 발걸음은 깨달음의 길 위에 올라섰습니다.$B$B여기서의 제 가르침을 가슴에 품고, 서쪽의 호수에서 되새기십시오.$B$B참을성 있게 연습을 반복하면, 조화와 깨달음을 얻을 수 있습니다. 그러면 지혜가 자유롭게 당신의 마음속으로 흘러들 것입니다.$B$B또한, 당신이 그렇게 멀리 떠난다면 코고는 소리가 제 명상을 방해하는 일도 없을 겁니다.$B$B이방인이여, 안녕히…"},objectives={{32,183541369},"비늘의 돌제단에서 명상해야 합니다."}}
rows[29871]={completion={{29,831920627},"어디서 본 적이 있는 것 같은데요?"},title={{12,1107364444},"영리한 애쉬요"},description={{392,1247479748},"영리한 애쉬요가 어디서 그 ≪영리한≫이라는 칭호를 얻었는지는 잘 모르겠습니다. 진위는 모두 똑똑해서 그들 중 더 똑똑한 친구라고 말하기도 그렇고 말입니다.$B$B사실 똑똑한 것과는 거리가 아주 멉니다.$B$B그래도 훌륭한 전사이긴 합니다. 춘 티엔 수도원에서 우리 훈련 임무에 선발되기에 충분한 실력을 보여줬거든요.$B$B애쉬요가 은둔 고수 찾는 것을 돕고 싶다면 네 바람의 계곡 북쪽 경계로 가보십시오."},objectives={{18,1523936768},"영리한 애쉬요를 찾아야 합니다."}}
rows[29872]={completion={{109,832514779},"아, 당신이었군요!$b$b아니, 아직 숨겨진 스승을 찾지 못했어요. 여기까지 온 게 시간 낭비였나 봐요.$b$b<한숨...>"},title={{13,59869138},"린 텐더포우"},description={{331,1588605930},"린은 자신이 생각하는 것보다도 더 뛰어난 재능을 가지고 있습니다. 하지만 주먹은 강력한데 비해 정신력이 좀 약합니다. 자신감만 더 가진다면 우리 중 가장 뛰어난 실력을 갖게 될 겁니다.$B$B린은 서쪽으로 향하는 여정에서 자기에게 필요한 확신을 찾게 될 겁니다. 지금쯤 돌밭을 향해 가고 있겠군요. 그곳에 가면 길을 멈추고 린과 대화해 보십시오."},objectives={{19,921706413},"린 텐더포우를 찾아야 합니다."}}
rows[29873]={completion={{65,1334858502},"이곳은... 정말... 너무 슬퍼! 켄켄은 이렇게 슬픈 곳은 본 적이 없어."},title={{7,1390738123},"컨컨"},description={{413,886492172},"그러니까… 호젠인 컨컨 말이군요.$B$B제 생각이지만, 수련을 통해 그 친구가 이정도 경지에까지 이른 게 참 인상 깊었습니다. 대부분 멍청한 그의 동족 중에서 머리도 그럭저럭 좋은 편이지요.$B$B컨컨이 동쪽으로 간다고 말했지만, 여기가 이미 네 바람의 계곡 가장 동쪽이니 그 친구도 여기서 멀리 가진 않았을 겁니다. 남쪽으로 길을 따라가면 보이는 크라사랑 밀림에 있는 쥬의 감시초소에서 그를 찾아보십시오. 그 친구가 뭘 발견했는지도 알아보시기 바랍니다."},objectives={{13,165938185},"컨컨을 찾아야 합니다."}}
rows[29874]={completion={{94,1193364419},"이 마을은 몇 주 전까지만 해도 없었던 것 같은데. 이 사람들은 어디서 온 거지?"},title={{17,1633856853},"가시덤불지팡이 캉"},description={"Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.$b$bI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave $r was looking out for him.","Kang의 자부심은 과한 경우가 자주 있어서 그를 위험한 길로 이끌곤 합니다. 지금 그가 가는 길은 아주 위험하고… 아, 크라사랑 밀림으로 갔으니까요.$B$B보통은 이방인에게 부탁을 하지 않는데… Kang이 무사한지 알아봐주시겠습니까? 당신 같이 용감한 $R|1이;가; 그를 보살펴준다는 걸 알면 마음이 한결 더 편해질 것 같습니다."},objectives={{23,1372230710},"Kang Bramblestaff를 찾아야 합니다."}}
rows[29875]={completion={{94,1193364419},"이 마을은 몇 주 전까지만 해도 없었던 것 같은데. 이 사람들은 어디서 온 거지?"},title={{17,1633856853},"캉 브램블스태프"},description={"Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.$b$bI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave $r was looking out for him.","캉은 자부심이 과한 경우가 자주 있어서 그것 때문에 위험한 길로 들곤 합니다. 지금 그가 가는 길도 아주 위험하고… 아, 크라사랑 밀림으로 갔으니까요.$B$B보통은 이방인에게 부탁을 하지 않는데… 캉이 무사한지 알아봐주시겠습니까? 당신 같이 용감한 $R|1이;가; 그를 보살펴준다는 걸 알면 마음이 한결 더 편해질 것 같습니다."},objectives={{23,1372230710},"캉 브램블스태프를 찾아야 합니다."}}
rows[29876]={title={{29,903978910},"세 번째 선장"}}
rows[29877]={completion={{76,2134245690},"고마워, 친구. 이제 호젠이 여기서 좀 일을 할 수 있겠네."},title={{26,1907999657},"뭘 알아야 농사를 짓지"},description={{374,2138456739},"토깽 놈들은… 우리 식량만 먹어치우는 게 아닙니다. 자기네들이 직접 농장을 만들려고 하거든요. 문제는… 뭐, 놈들이 멍청하다는 거지만.$B$B제 말을 못 믿으시겠다고요? 어젯밤 이놈들이 우리 농기구 창고에 숨어들어서… 농기구를 훔쳐갔습니다. 그리고 우리가 일어나서 보니 갈퀴와 손수레가 땅에 묻혀 있었지요.$B$B놈들은 거기에다 물을 주고 있었습니다. 손수레를 키우려고 했단 말입니다!$B$B밖에 나가면 제발 우리 농기구 좀 파내와 주십시오."},objectives={{35,232490309},"농기구 7개를 피내야 합니다."}}
rows[29878]={title={{28,2095083446},"호젠 포획"},description={{327,286118359},"이제 한 가지는 머리가 아플 만큼 분명합니다. 호젠은 미끈고기를 매우 좋아합니다.$B$B명상에 깊이 잠긴 동안, 흐릿한 영상과 묘한 느낌이 당신의 마음을 채웠습니다. 이제 온전히 정신을 차리고, 그때의 경험을 이해해보려고 노력합니다.$B$B해괴한 계획이 머릿속에 자리잡기 시작합니다. 어쩌면 너무 이상해서 효과가 있을지도 모릅니다…"},objectives={{65,1582395157},"키티타타 호수에서 미끈고기 8마리와 온전한 도자기 병 8개를 모아야 합니다."}}
rows[29879]={completion={{113,2114920951},"위켓이 호젠을 구해줄까? 그리고 슬리키를 데려올까? 흠, 위켓도 나쁘지 않을지도 몰라. 어쨌든 투키 투키는 두크 우켐을 좋아하지 않았어..."},progress={{31,1376633055},"위켓이 나한테 슬리키를 줬어!?"},title={{15,978012750},"꿀꺽 삼켰어요"},description={{432,1349066786},"자, 이제 자네 고민을 다시 생각해 보세.$B$B우리 판다렌이 그랬던 것처럼, 자네들도 호젠과 우호적인 관계가 될 수 있을 거라고 믿네.$B$B내 뒤쪽에 난 오솔길을 따라가면, 호젠이 물고기를 잡는 호수를 찾을 수 있을 걸세.$B$B해마다 이맘때가 되면, 무시무시한 야수가 그 호수에 정착하고 굶주린 호젠들을 여럿 잡아먹곤 한다네.$B$B그렇게 희생될 뻔한 호젠들을 구출해 주고 물고기도 잡아 준다면, 아마 호젠도 자네를 달리 보게 될 거야."},objectives={{91,2060391500},"키티타타 호수에 있는 게걸스러운 악어에게서 호젠 5마리를 구해주고, 얼룩 송어 5마리를 모아야 합니다."}}
rows[29880]={title={{18,672746364},"오종오금"},description={{191,1280124450},"병 하나에 물고기를 한 마리씩 넣을 때마다 긍정적인 느낌이 커집니다.$B$B정말로 성공할지도 모릅니다! 계획이 이상적으로 풀리고 급조한 함정에 붙잡힌 호젠을 모두 풀어준다면, 호젠도 당신에게 더 호의적인 태도를 보일 것입니다.$B$B이제 미끼를 놓을 시간입니다."},objectives={{77,394815820},"누카 누카 야영지에서 호젠 덫을 사용해야 합니다. 그리고 호젠이 붙잡히면 덫을 깨뜨려서 붙잡힌 호젠 5마리를 풀어줘야 합니다."}}
rows[29881]={completion={{83,367247892},"아! 친구분은 색감을 보는 눈이 정말 뛰어나시군요. 이 재료들로 훌륭한 안료를 만들 수 있겠어요."},progress={{107,347083971},"꽃잎이 떨어진 후 완벽한 색조를 얻기 위해 사용할 수 있는 시간은 아주 짧습니다."},title={{17,1318034929},"완벽한 색"},description={{351,740926903},"이미 보셨겠지만, 이곳의 나무에는 아름다운 분홍빛 꽃잎이 잔뜩 달렸습니다. 꽃잎은 시간이 지날수록 그 색에 깊이가 더해지면서 점차 바랩니다.$B$B이런 말씀을 드리기는 죄송하지만, 사실 제가 갓 떨어진 꽃잎이 조금 필요합니다. 그렇게 갓 떨어진 꽃잎들만이 제가 추구하는 색을 낼 수 있거든요.$B$B그런 꽃잎들만 있으면, 숨막힐 듯 아름다운 색의 잉크를 만들 수 있습니다. 도와주시겠습니까?"},objectives={{31,1284040289},"갓 떨어진 꽃잎 8개를 모아야 합니다."}}
rows[29882]={completion={{93,1957100998},"여행자여, 고맙습니다. 이것들로 훌륭한 깃펜 세트를 만들 수 있겠군요. 수고에 대한 보답으로 이것 하나 드리겠습니다."},progress={{140,48650837},"벌침 좀 구하셨나요? 보통 이런 건 스님께 여쭤보는데, 지금은 다들 다른 곳에 계신 것 같네요."},title={{17,360581034},"독침 붓촉"},description={{345,1071477464},"완벽한 선을 그리려면, 적절한 도구를 사용해야 합니다. 그런데 제 붓은 이제 손볼 수 없을 만큼 망가져 버렸습니다. 붓촉이 호젠 머리털처럼 뻣뻣해져서 글씨는 커녕 낙서도 할 수 없지요.$B$B도원 여기저기를 돌아다니는 말벌을 보셨습니까? 놈들의 독침으로 촉을 만들면, 아주 날카로운 선을 그릴 수 있습니다.$B$B저를 위해 독침을 몇 개 모아 주시겠습니까?"},objectives={{42,855977386},"도원 말벌에게서 말벌 독침을 6개 모아야 합니다."}}
rows[29883]={completion={"It sounds like you made quite the good impression.$B$BWell done, $n!","아주 좋은 인상을 남기신 것 같네요. 잘하셨어요!"},title={{22,876201115},"진주지느러미 마을의 상황"},description={"I've been thinking.$B$BWe are cut off from support and a long way from home.$B$BAlthough these Pearlfin jinyu mistrust our presence, they do not appear to be hostile.$B$BIf we could convince them that we are their friends, an alliance between our races could prove extremely valuable.$B$B$n, you must go speak to the jinyu around the village.$B$BConvince their leaders that we are not to be feared, and that we only wish for peace.","제가 얼마간 생각을 해봤습니다. 잠시만 제 얘기를 들어 주십시오.$B$B우리는 조난 당하고, 굶주리고, 길을 잃고, 고향에서 멀리 떨어진 곳에 떨어졌습니다.$B$B이 진주지느러미 진위가 아직 우리를 진심으로 받아들이지는 않았지만, 아직까지는 적대적인 태도를 보이지 않고 있습니다.$B$B저들에게 우리가 아군이라는 사실을 확인시켜 준다면, 매우 가치 있는 우호 관계를 맺을 수 있을 것입니다.$B$B$N 님, 마을 주위의 진위들과 이야기를 나눠 주십시오.$B$B저 종족의 지도자들에게 우리가 두려워할 존재가 아니고, 오직 평화를 원하는 존재라는 사실을 전해 주십시오."},objectives={{98,607094976},"진주지느러미 마을에 있는 장로 루샨, 진주지기 푸진, 교관 샤프핀, 오트템도와 대화해야 합니다."}}
rows[29884]={title={{27,664650204},"정찰병 출발"},description={{289,1504314958},"이제 설리와 제가 떠날 시간입니다. 눈에 불을 켜고 White Pawn의 흔적을 찾고, 곧 보고하겠습니다.$B$B죄송합니다만, 테일러 제독님께서 몸을 추스르시는 동안 당신이 이곳을 맡아 주십시오. 우리가 자리를 비운 동안 진위들에게 많은 이야기를 들어 주십시오. 저희가 돌아오면 모두 보고하시기 바랍니다."},objectives={{41,634793998},"정찰병이 떠나는 모습을 지켜보고, 덩치 큰 루와 대화해야 합니다."}}
rows[29885]={completion={"This should be plenty, $n. Thanks.","이 정도면 충분할 것 같습니다, $n. 감사합니다."},progress={{108,1323256489},"시간이 얼마 남지 않았습니다. 한 시간이라도 지체하면 흰 폰이 더 멀리 이동할 수 있습니다. 제가 요청한 물품들은 어디 있습니까?"},title={{12,195694329},"전투 식량 준비"},description={{319,144462241},"제독님이 회복할 때까지 마냥 기다릴 수만은 없습니다.$B$B설리와 제가 북부 지역에서 안두인 왕자님을 찾아볼 예정입니다만, 이번 작전에는 보급품이 더 필요합니다.$B$B이곳 호수에는 야생 동물이 우글거립니다. 그리고 사냥을 해도 좋다는 허가까지 받았습니다.$B$B설리와 제가 작전 준비를 마무리하는 동안, 가서 보급품을 모아오십시오."},objectives={{26,1905792819},"거북 살코기 6개를 모아야 합니다."}}
rows[29886]={title={{11,1018048535},"참선의 치유력"},description={"Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure.$B$BLuckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries.$B$BThe flowers growing on the surface of Glass Lake are needed to make the antidote.$B$B$n, go quickly and bring back some blooms. Your Admiral's life depends on it.","당신 친구 테일러 제독은 위독한 상황입니다. 안타깝지만, 호젠의 독에 중독된 상처는 치유하기가 쉽지 않습니다.$B$B하지만 우리 부족은 지금까지 몇 세대에 걸쳐 호젠과 싸우다 보니, 이런 상처를 치유할 수 있는 약을 만들 수 있었습니다.$B$B유리 호수의 표면에서 자라는 꽃으로 해독제를 만들 수 있습니다.$B$B$N 님, 가서 꽃을 몇 송이 가져오십시오. 제독의 생명이 그 꽃에 달려 있습니다."},objectives={{20,888086665},"참선의 연꽃 6송이를 모아야 합니다."}}
rows[29887]={completion={"You found them? Oh thank the spirits of water!$B$BYou have saved my tailfin, $n.","찾았다고요? 오, 물의 정령이시여, 감사합니다! 당신 덕분에 제 꼬리 지느러미를 구했어요."},progress={{70,1079834825},"그 장로는 물과 소통하는 자입니다. 그가 물에게 말하면 물이 대답합니다."},title={{23,1050113742},"장로의 장비"},description={{347,1938446485},"이런, 이런, 맙소사… 장로님이 알아차리시면 안 되네!$B$B아무래도 탈출할 때 장로님의 의식용 장비를 모두 놓고 온 모양이네.$B$B그런데… 이제 문워터 은거지를 호젠이 온통 점령하고 말았어!$B$B그 소중한 장비들을 이렇게 모두 잃어버리다니, 난 진주지기 자격이 없네.$B$B<두 손에 얼굴을 묻는 늙은 진위>$B$B이방인이여, 부디 나를 도와줄 수 있겠나?"},objectives={{108,600428738},"줄꼬리 끈끈발에게서 물예언자의 지팡이, 의식용 로브, 비취 왕관, 장미목 묵주를 되찾아야 합니다."}}
rows[29888]={completion={{111,390548306},"텅 빈 집을 둘러봅니다. 제대로 찾아온 것 같지만, 거주자의 흔적은 전혀 없습니다."},title={{23,646249369},"전승지기를 찾아서"},description={{405,1175024542},"당신과 당신 동료들이 안두인 왕자를 찾아내려고 애쓰고 있다는 사실을 잘 알겠네.$B$B그 문제에 도움을 줄 수 있는 이가 있지. 이 땅에 대해 누구보다도 잘 알고 있는 판다렌 전승지기네. 자네를 어떻게 받아들일지는 잘 모르겠지만, 서로에 대해 궁금한 점이 많을 것이라는 점만은 분명하겠지!$B$B전승지기는 남서쪽 숲에 살고 있네. 가서 진주지느러미 부족에게 이야기를 들었다고 전하게."},objectives={{71,496617960},"비취 숲, 꿈꾸는 자의 정자에 있는 전승지기 초를 찾아야 합니다."}}
rows[29889]={completion={{297,277644884},"당신네 사람들이 우리 해안에 표류해 왔다는 소식을 들었지만, 바로 내 집 문앞에 표류해 올 줄은 몰랐군! 낯선 이여, 무슨 일로 여기에 왔나? 당신은 안두인 왕자를 찾고 있다고 설명하고, 판다렌들에게 그 소년에 대해 묘사합니다. 매우 흥미롭군! 진주지느러미가 당신을 내게 보낸 것이로군, 그렇지?"},title={{13,849926574},"술은 공짜 술이 제 맛"},description={{94,1644022522},"달콤한 향기가 탁자 위의 병에서 풍겨 옵니다.$B$B잠깐 맛을 봐도 큰일이 나지는 않겠지요?"},objectives={{29,1620265580},"군침도는 맥주를 맛봅니다."}}
rows[29890]={completion={{178,289380644},"어떻게 저를 찾으셨죠?<안두인은 당신이 드림 브루에서 본 환상에 대해 설명하는 것을 듣습니다.>놀랍군요! 며칠 전에 정확히 그런 일이 있었습니다. 그 이후로 우리는 잠잠히 지내왔습니다."},title={{19,1827861129},"중심을 찾아서"},description={{326,1780431987},"꿈결 맥주가 완성되었네! 이번에는 이 맥주를 마신 다음, 내면의 집중 상태에서 환영을 받아들여야 하네.$B$B저기 탑까지 나를 따라오게. 우리 판다렌은 내면의 평온을 매우 중시하는데, 그 방법을 자네에게도 가르쳐 주겠네.$B$B혼란스러운 마음이 계속해서 자네가 정신을 집중하지 못하게 방해하겠지만, 중심을 유지해야 한다는 것만 기억하게."},objectives={{88,1670860144},"비취 숲, 꿈꾸는 자의 정자에 있는 탑에서 전승지기 초와 함께 명상해야 합니다."}}
rows[29891]={completion={{82,657701227},"정말 놀라운 표본이네요! 사실, 당신이 성공했다는 사실에 상당히 놀랐습니다."},progress={{56,1030714849},"안개는 마치 제멋대로인 것 같지 않나요?"},title={{7,509685536},"진한 맛"},description={{398,1712177684},"꿈결 맥주를 만들려면, 몇 가지 재료가 필요합니다.$B$B우선 그 맛을 더욱 진하게 하기 위해, 무시무시한 공포의 안개도깨비에게서 재료를 구해야 합니다.$B$B이 생물은 안개가 가장 자욱한 곳에서만 나타난다는 이야기가 있습니다.$B$B여기서 북동쪽으로 가면, 늪지에 소름끼치는 안개도깨비들이 돌아다니는 것을 보실 수 있을 겁니다. 이 생물들을 처치하다 보면 공포의 안개도깨비가 나타날 텐데, 놈을 처치하고 그 심장을 제게 가져오십시오."},objectives={{81,1732689218},"공포의 안개도깨비가 나타날 때까지 소름끼치는 안개도깨비를 처치해야 합니다. 그 후에 공포의 안개도깨비를 처치하고 공포의 안개도깨비 심장을 획득해야 합니다."}}
rows[29892]={completion={{42,113620648},"당신이 사는 곳에는 악어가 있나요?"},progress={{44,1436832726},"늪지대에서는 발조심하렴, 내 새 친구야."},title={{4,222231010},"달콤한 향기"},description={{200,1218849645},"술의 향기는 매우 중요하지만 간과되기 쉬운 요소지.$B$B정갈하면서도 달콤한 향기를 만들어 내려면, 동쪽에 있는 수렁악어에게서 온전한 눈알을 모아야 하네.$B$B조심하게. 꽤나 사나운 동물이니까."},objectives={{54,1461797320},"수렁악어에게서 온전한 악어 눈 5개를 모아야 합니다."}}
rows[29893]={completion={{146,397800353},"아름다운 색상, 보기 드문 투명도, 반짝임은 있지만 번쩍거리지 않는... 이 제품은 꽤 괜찮을 것 같네요. $B$BI, 당신에게서 큰 잠재력을 보기 시작했어요, 참 신기한 분이시군요."},progress={{81,1448646469},"재료를 모두 모으셨나요? 이제 곧 드림 브루를 만들 시간입니다."},title={{3,1800172},"매혹적인 빛깔"},description={{258,817473660},"꿈결 맥주의 가장 독특한 점은 바로 그 무지갯빛 꿈꾸는 듯한 빛깔입니다.$B$B동쪽으로 가면 반짝이는 호박말벌을 보실 수 있을 겁니다. 그 말벌의 날개가 있어야 술의 반짝이는 빛을 뽑아낼 수 있습니다.$B$B이 칼을 가지고 가서 날개 8장을 모아 오십시오."},objectives={{25,21794410},"호박말벌 날개 8장을 모아야 합니다."}}
rows[29894]={completion={"I saw the vision, $n. What do you think it means?$B$BI think it is clear that you play some part in it.","나는 그 환상을 봤어요, $n. 그게 무슨 의미라고 생각하세요?$B$B 당신이 그 일에 어떤 식으로든 관여하고 있다는 건 분명해 보여요."},title={{20,1293581660},"물의 정령"},description={{240,486473472},"호젠과의 전쟁이 끝없이 계속되고 있네. 그래서 우리 부족의 미래는 불확실하다고 밖에 할 수 없지.$B$B그래서 우리 물예언자께서 물의 지혜를 구하기로 결정하신 것이네.$B$B루샨 장로님이 기다리고 계시네. 어서 자네가 모은 장비들을 가지고 장로님을 찾아가게. 그러면 의식이 시작될 걸세."},objectives={{62,1400719382},"장로 루샨과 대화하고 물예언의 의식을 지켜봐야 합니다."}}
rows[29895]={completion={"This is Anduin's cloak, $n!$B$BThis must mean he passed through this forest.$B$BWe must heighten our efforts to find him.","이것은 안두인의 망토입니다! 그가 이 숲을 지나갔다는 뜻이 틀림없습니다. 우리는 그를 찾기 위한 노력을 더욱 강화해야 합니다."},title={{23,2110281142},"하얀 졸의 흔적"},description={{154,727307296},"이 망토는 낡고 찢어졌지만, 눈에 띌 만큼 섬세한 마감과 왕실 문장을 분명히 알아볼 수 있습니다.$B$B당장 얼라이언스 사령관에게 보여줘야 합니다."},objectives={{72,955079649},"비취 숲의 진주지느러미 마을에 있는 제독 테일러에게 망토를 보여줘야 합니다."}}
rows[29896]={title={{16,1153291774},"밥 대신 스테이크"},description={{441,370672437},"이왕 여기까지 나왔으니, 빈 손으로 돌아갈 수는 없죠. 안 그래요?$B$B자, 혹시 이 부근의 호저들에게서 아주 귀하고 정말 깜짝 놀랄 만큼 맛있는 스테이크를 구할 수 있다는 사실을 아시나요?$B$B그 날카로운 가시 때문에 사냥하기가 어렵긴 한데, 당신이라면 자기 앞가림은 충분히 하실 것 같네요.$B$B가서 스테이크를 몇 개 모아 주세요. 야영지로 가져가게요.$B$B당분간은 여기 야생의 땅에서 조금 불편하게 지내야 할 것 같지만, 그래도 식사는 왕처럼 해야죠!"},objectives={{27,609507148},"호저 스테이크 5개를 모아야 합니다."}}
rows[29897]={title={{29,126829529},"세상에 공짜는 없다"},description={{279,507207208},"전투는 끝났어요. 하지만 문제가 모두 해결된 건 아니에요. 아직 멀었다고요.$B$B야영지 전체에서 보급품이 빠른 속도로 소모되고 있어요. 하지만 보급장교가 전투에서 돌아오지 않아서, 뭘 어떻게 해결해야 할지 전혀 모르겠어요.$B$B몇몇 병사들이 그녀가 북쪽 숲으로 끌려가는 모습을 봤다고 하더라고요.$B$B부디… 그녀를 찾아 주시겠어요?"},objectives={{62,699769455},"비취 숲의 청록 숲에서 산드라 에메렐라를 찾아야 합니다."}}
rows[29898]={completion={"The healing waters should abate Ren's fever for a short while, but alas, I fear it is no permanent cure.$B$BThank you, $c. We have granted him a little more time, at least.","치유의 물은 렌의 열을 잠시 동안 내리게 하겠지만, 안타깝게도 영구적인 치료법은 아닌 것 같습니다. 감사합니다, $c. 적어도 그에게 조금 더 시간을 벌어주었습니다."},title={{13,1083209880},"신성한 물"},description={{361,1079573516},"저를 구하러 여기까지 와주시다니, 정말 고마워요. 저기 누워 있는 렌은 저 때문에 크게 다쳤어요.$B$B절 도와줄 이유가 전혀 없었는데도 절 구하기 위해 목숨을 걸었거든요.$B$B열이 높아지기 전에, 이 언덕 아래쪽의 동굴에 치유의 물이 있다는 말을 하더군요.$B$B이곳은 무척 위험한 곳이지만, 제 친구를 구하기 위해서는 뭐든 해야 해요. 저와 함께 그 물을 가져오실 수 있으실까요?"},objectives={{71,874105459},"슬픔의 동굴에 있는 신성한 그릇 4개에서 치유의 물을 모아야 합니다."}}
rows[29899]={completion={{77,1753904350},"고마워요, 친구. 영혼들이 평안히 잠들었다는 걸 알게 되어 기쁩니다."},title={{13,526461119},"평화롭게 잠드시오"},description={{195,1990225032},"저 안의 영혼들이… 고통에 찬 비명을 지르오…$B$B이 세상에… 갇혀… 다음 세상으로… 가지 못하고…$B$B그들의 비명이 그치지 않는다면… 나는… 미치고 말 것이오…$B$B부디… 그들에게 안식을 찾아 주시오."},objectives={{24,669856154},"고통받는 영혼 6마리를 처치해야 합니다."}}
rows[29900]={completion={{76,1017947625},"아... 그 시였군요! 읽어보셨어요? 베일에 대해 뭘 알게 되셨어요?"},progress={{27,1889591795},"혹시… 그 두루마리를 찾으셨나요?"},title={{17,643453754},"영원꽃 골짜기"},description={{479,795732335},"아버지는 평생을 바쳐 영원꽃 골짜기에 대해 연구하셨어요.$B$B그 골짜기는 12,000년 전, 판다렌 혁명이 있은 후에 봉인된 신비한 장소랍니다. 지금까지 알려진 바가 거의 없어요!$B$B아버지께서는 어떤 실마리를 쫓아 언덕 아래쪽에 있는 동굴을 찾아 오셨어요. 그 안에는 골짜기의 노래라는 옛 시가 숨겨져 있다고 하는데, 안타깝게도 지금은 그걸 찾아오실 수 있는 상태가 아니세요. 어떤 고대의 영혼이 그 시를 지키고 있다고 하더군요.$B$B혹시 동굴에 가시는 길이라면, 그 시를 가져오실 수 있을까요?"},objectives={{53,1028667744},"슬픔의 동굴에서 골짜기의 노래를 회수해야 합니다."}}
rows[29901]={completion={{307,365565655},"그가 뭐라고?!?!?$B$B내가 아직 그를 못 찾은 게 다행인 줄 알아. 만약 찾게 된다면 내가 직접 죽여버릴지도 몰라!$B$B그가 대체 무슨 생각을 하고 있는 건지... 베일을 쫓아다니다니... 왕자답지 못한 행동이야!$B$B지금 당장 더 급한 일이 없었다면 함대 전체를 보내서 그놈을 쫓게 했을 거야!"},title={{17,1004070215},"안두인의 결정"},description={{241,133164771},"왕자님의 친구들을 위해 할 수 있는 일은 모두 했습니다.$B$B하얀 졸, 즉 안두인 왕자를 찾아내는 임무도 완수했습니다. 테일러 제독님과 다른 SI:7 요원들이 어서 왕자님을 만나고 싶어할 겁니다.$B$B이제 집으로 돌아갈 시간입니다."},objectives={{43,1654279308},"안두인에게 집에 갈 시간이라고 말해야 합니다."}}
rows[29902]={title={{19,299909530},"화염과의 혈투"},description={{339,1953724682},"저 원숭이들은 지성보다는 야성을 앞세우는 짐승들입니다. 하지만 불이 막강한 무기가 될 수 있다는 사실을 알고 있기는 한 것 같습니다.$B$B저 불길을 처리하지 않고 내버려 둔다면, 지금까지 우리가 건설한 것을 모두 집어삼키리라는 것은 굳이 말씀드릴 필요가 없을 것 같군요.$B$B다른 병사들은 이미 바삐 뛰고 있으니, 당신이 도와주셔야 겠습니다. 이 물통을 가지고 불을 꺼 주십시오!"},objectives={{35,1935169061},"무법천지 상륙지에서 6곳의 불을 꺼야 합니다."}}
rows[29903]={completion={{52,1355503013},"좋아. 이제 저 호드 잡종들이 얼굴을 드러내게 놔두자!"},title={{15,109479921},"완벽한 짝"},description={{368,635257245},"루샨 장로와 저는 양측이 함께 힘을 모으는 것이 최선이라고 의견을 모았습니다.$B$B우리는 우수한 군사 지식과 무기를 진주지느러미 일족과 공유할 것입니다.$B$B그 대신, 저들은 우리가 다시 호드와 맞서 싸울 때 든든한 아군이 되어주기로 했습니다.$B$B이 무기와 장비 상자를 받으십시오. 마을을 돌아다니면서 진위들을 각자의 능력에 알맞은 장비로 무장시키십시오."},objectives={{67,340992145},"진주지느러미 수병과 대화하고 적절한 장비로 무장시켜야 합니다."}}
rows[29904]={completion={"Your trainees returned recently. I could hardly believe my eyes! They did not look like the same jinyu that you left with.$B$BExcellent work, $c. Couldn't have done better myself.","훈련생들이 최근에 돌아왔는데, 제 눈을 믿을 수가 없었어요! 당신이 데려갔을 때의 진유와는 전혀 다른 모습이더군요. 정말 훌륭한 일을 해냈습니다, c. 제가 직접 했어도 이만큼은 못했을 거예요."},title={{18,962817651},"생선은 푹 익혀야 제 맛"},description={{214,492156792},"똑똑하고 젊은 진주지느러미 수련생들을 선발해서 부대를 조직했습니다만, 모두들 실전 경험이 필요합니다.$B$B부대를 이끌고 북동쪽 대나무 밀림으로 가서, 야생동물들을 보이는 대로 처치하십시오.$B$B수련생들이 전투에 투입될 수 있게 준비를 마치기 전에는 돌아올 생각도 하지 마십시오."},objectives={{69,1523717778},"대나무 밀림에서 야생동물 24마리를 처치하며 진주지느러미 우수생들을 훈련시켜야 합니다."}}
rows[29905]={completion={"The waters were right about you, $n. Because of your efforts, this village has a future. We will not forget the lessons you've taught us, $c.","물길이 바로 당신 발치에 있었어요, $n. 당신의 노력 덕분에 이 마을에 미래가 생겼습니다. 당신이 우리에게 가르쳐준 교훈을 잊지 않겠습니다, $c."},title={{13,1501681847},"아름답게 불타올라라"},description={{316,706686026},"최전방 정찰조에서 보내온 보고에 따르면, 줄꼬리 구덩이의 호젠들이 북부 부족 출신의 지원군들과 세력을 합치고 있다고 합니다.$B$B우리 병력은 북서쪽 마루에서 모여 전투 준비를 하고 있습니다. 모두 당신만 기다리고 있지요.$B$B이제 우리의 진짜 힘을 보여줄 시간입니다. 적을 끝장낼 시간입니다."},objectives={{53,1771439271},"그루끼끼 지원병 또는 줄꼬리 신병 15마리를 처치해야 합니다."}}
rows[29906]={completion={"Without their leader, these hozen should once again settle into disarray.$B$BToday we rejoice in our victory! $n, you came to us a stranger, but you depart as a friend.$B$BFrom henceforth, you are the highest of the high - a valued friend and defender of the Pearlfin tribe.","지도자가 없으니 이 호젠들은 다시 혼란에 빠질 것이다. 오늘 우리는 승리를 기뻐한다! 자네는 우리에게 낯선 이였지만 친구로 떠난다. 이제부터 자네는 최고의 영웅이자 진주지느러미 부족의 소중한 친구이자 수호자가 될 것이다."},title={{9,536648232},"잉어의 잉여한 힘을 모아"},description={"Despite the hozen's apparent disarray, there is an order to their chaos. Their leader, Chief Gukgut, is the shrewd mastermind behind their attacks.$B$BHe is organizing their movements at the great pit at the hozen camp to the northwest.$B$BStrike now and show him no mercy, $n, for he will do the same.","호젠이 혼란에 빠져 있는 것 같지만, 그 혼돈 속에도 나름의 질서를 유지하고 있습니다. 적의 지도자인 구크구트 족장이 공격을 주도하는 기민한 중심 축이라고 할 수 있겠습니다.$B$B놈은 북서쪽 호젠 야영지의 거대한 구덩이에서 적의 움직임을 지휘하고 있습니다.$B$B지금 공격해서 무자비하게 처벌해 주십시오, $N. 아마 놈도 우리를 그렇게 할 준비를 하고 있을 겁니다."},objectives={{18,518678592},"족장 구크구트를 처치해야 합니다."}}
rows[29907]={completion={{160,2097647972},"어서 오세요, 손님! 제 아들이 재배한 순무를 맛보러 오셨나요? 아니면 돼지를 몇 마리 사러 오셨나요? 편히 쉬세요. 자리는 넉넉합니다."},title={{14,1889461616},"첸과 리 리"},description={"My niece and I are new to Pandaria. Probably like yourself. We're visitors from the Wandering Isle, and, to be honest, we have no idea where we're going.$b$bThat farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What do you say, Li Li?$b$b$R? Would you like to share the road with us?","조카와 나는 판다리아에 처음 왔다네. 아마 자네도 마찬가지겠지. 우리는 유랑도에서 왔는데, 솔직히 말하면 어디로 가는 중인지도 잘 모르겠군.$B$B저기 보이는 농장은 신발을 벗어 던지고 맥주나 마시기 아주 딱인 것 같지 않나. 리 리, 너는 어떠냐?$B$B$R 양반, 우리와 함께 가는 게 어떻겠나?"},objectives={{39,1014925288},"팡의 농장까지 첸 스톰스타우트를 따라가야 합니다."}}
rows[29908]={completion={"<Pang surveys the area around his farm.>$b$bWell, they're not ALL gone yet, but there's less of them. And they aren't holding their ears quite as high anymore.$b$bI'd guess that they're scared of you, $n.","<팡은 농장 주변을 둘러보았다.>$b$b음, 아직 다 사라진 건 아니지만 수가 줄었군. 그리고 예전처럼 귀를 쫑긋 세우지도 않았고.$b$b아마도 자네를 무서워하는 것 같네, $n."},title={{28,1592809236},"끝없는 골칫거리"},description={{371,457646869},"이곳 상황이 좋지 않아 사과드리겠습니다. 토깽 놈들이 언덕 아래에서 우리 가족 농장과 농작물이 있는 곳으로 들어오려고 계속 밀어붙이고 있습니다. 원래 우리 농작물이 맛이 더 좋고 알도 굵어서 말이지요… 하여튼 이놈들 때문에 골치가 아픕니다.$B$B저는 군인이 아니지만… 당신은 군인 같아 보이는군요! 우리 땅에서 저놈들 좀 몰아내 주시겠습니까?"},objectives={{95,2113568262},"토깽 정찰꾼, 토깽 일꾼 또는 토깽 말썽꾼 10마리를 처치해야 합니다."}}
rows[29909]={completion={{112,57023209},"뭐? 누구야...? 아버지가 보냈어? 쳇... 아버지는 가끔 너무 참견이 심해. 난 모든 걸 잘 처리하고 있어."},title={{18,801216129},"줄어드는 농작물 생산량"},description={"Your help here is appreciated, $n. I'd like to give you another job, if you're interested.$b$bMy son, Ang, runs the small farm just down this hill. He should have brought me some fruits and vegetables this morning, but I haven't seen him all day.$b$bWould you go down there and see what's going on?","$N 님, 도움을 주셔서 감사합니다. 관심이 있다면 제가 다른 일을 하나 드리고 싶군요.$B$B제 아들 앙은 이 언덕 아래에서 작은 농장을 꾸리고 있습니다. 오늘 아침에 채소와 과일을 제게 조금이라도 가져왔어야 하는데, 하루 종일 보이지를 않는군요.$B$B그곳으로 가서 무슨 일이 있는지 알아봐 주시겠습니까?"},objectives={{21,1912946643},"앙 썬더풋을 찾아야 합니다."}}
rows[29910]={completion={"Thank you, $gsir:ma'am;! Now I can get back to my chores.","감사합니다, 부인! 이제 다시 제 할 일을 할 수 있겠네요."},title={{17,351109037},"날뛰는 쥐들"},description={{277,214685227},"아침에 아빠가 토깽 놈들과 싸우시는 걸 보려고 잠깐 자리를 비웠어요. 되돌아와 보니 농장에 쥐새끼들이 득시글거리고 있더라고요!$B$B저는 그것들을 죽이고 싶지 않지만, 없애버리기는 해야 해요. 아, 그렇지! 놈들이 파놓은 구멍을 막으면 되겠어요!$B$B쥐들이 구멍 밖으로 더 튀어나오지 못하도록 흙으로 메워주세요."},objectives={{73,129248291},"썬더풋 농장에서 통통한 마모트 6마리를 몰아내고 마모트 구멍 6곳을 막아야 합니다."}}
rows[29911]={completion={{37,599148958},"호호! 바로 이거야!"},progress={{19,1587761858},"순무 냄새가 나는 것 같은데?"},title={{27,1263652696},"완벽하기 그지없는 수확물"},description={"Here, $n. My father will be wanting this.$b$bThank you, again, for helping with the virmen.","$N 님, 여기 있습니다. 아버님께서 이걸 찾고 계실 겁니다.$B$B토깽 문제를 도와주셔서 다시 한 번 감사 드립니다."},objectives={{51,2141086622},"팡 썬더풋에게 신선한 청과물 상자를 가져가야 합니다."}}
rows[29912]={completion={{169,478839252},"삼촌 농장에서 음식을 보내주신 분이 당신이시죠. 감사합니다. 제 돼지들은 입맛이 까다로운 편인데, 저 순무랑 수박은 정말 좋아해요."},title={{23,1575016896},"굉장한 패니 양"},description={{426,1962026340},"이 채소 대부분은 내다 팔겠지만, 가족을 위해 조금은 남겨두고 싶습니다. 특히 제 조카인 리앙이 돼지를 기르는 데 필요하니까 말입니다.$B$B공교롭게도 리앙의 사육장으로 가는 길은 지금 토깽 놈들이 들끓고 있습니다. 그러니 패니 양에게 도움을 요청해야겠군요.$B$B우리가 모아놓은 야채를 제 집 옆에 서 있는 패니 양에게 가져다주십시오. 그런 다음 패니 양에게 배달을 부탁해야 합니다. 부탁은 아주 예절 바르게 하십시오! 리앙의 사육장으로 그 채소를 보내야 하니까요."},objectives={{168,1418382944},"앙의 거대한 분홍색 순무와 앙의 여름 수박, 그리고 팡의 불두부를 패니 양에게 가져가서 배달을 부탁해야 합니다. 세 가지 모두 썬더풋 사육장에 안전하게 도착해야 합니다."}}
rows[29913]={completion={"<Liang sorts through the meat.>$b$bYou're not just a $c, but you're a butcher, too? You've got an eye for quality pig food, neighbor.$b$b<Liang throws the meat into the muddy pit below.>","<량은 고기를 분류한다.>$b$b당신은 그냥 $c가 아니라 정육점 주인이기도 한가? 좋은 돼지고기를 고르는 눈이 있군, 이웃.$b$b<량은 고기를 아래 진흙 구덩이에 던져 넣는다.>"},progress={{147,436666312},"돼지들이 굶주려서 꽥꽥거리는 소리를 들으면 귀가 아파요. 하지만 돼지 농장을 좀 하다 보면 굶주린 돼지의 꽥꽥거리는 소리와 일반적인 꽥꽥거리는 소리를 구분할 수 있게 되죠."},title={{20,1044954993},"돼지가 먹을 고기"},description={{422,455975296},"조금 전에도 말씀드렸지만, 제가 기르는 돼지들은 입맛이 까다롭습니다. 튼튼하게 자라려면 고기를 먹어야 하는데, 양고기나 야크 고기는 좋아하지 않습니다. 돼지고기는 어떤 것이라도 먹이지 않을 생각이고요.$B$B그런데 돼지들이 무샨 야수의 고기는 정말 게눈 감추듯 먹어치우더군요. 또 거북이 고기라면 아주 환장합니다. 무샨 야수와 거북이는 서쪽에 가면 많이 돌아다닙니다.$B$B제 사냥 실력은 솔직히 정말 형편없습니다. 이 어린 돼지들과 주인장을 도와주시지 않겠습니까?"},objectives={{58,825606285},"무샨 어깨 스테이크 4개와 거북살점 조각 80개를 획득해야 합니다."}}
rows[29914]={completion={{140,2050561887},"저기 있네! 셋 다 다시 우리 안으로 들어가! 자, 어서!<리앙이 당신을 올려다봅니다.> 고마워요, 이웃님. 정말 도와주셔서 감사해요."},progress={{60,1799046159},"찾으셨나요? 세 개가 빠진 것 같은데요."},title={{15,619860069},"돼지 찾기"},description={{282,1342420861},"돼지 수를 계속 세면서 몇 마리인지 알아두려고는 하고 있는데, 가끔가다 조금씩 없어지는군요. 이 토깽 놈들이 온통 헤집고 돌아다니는 통에 제가 잠시 정신을 놨더니 돼지 몇 마리가 도망쳐버렸습니다.$B$B도망친 돼지들을 좀 찾아봐 주시겠습니까? 저라면 서쪽에 있는 언덕부터 찾아볼 겁니다."},objectives={{28,710745503},"지엔, 링과 구린내를 찾아야 합니다."}}
rows[29915]={completion={{110,1608632816},"그 어린 양을 내게 데려오지 말았어야 했어. 그 애는… 여기보다 돼지우리에서 훨씬 안전했을 거야."},progress={{37,2139617845},"어머... 제 양 한 마리를 가지고 계신 건가요?"},title={{17,556973416},"이웃의 의무"},description={{284,941351652},"가축 수가 모자란 게 저뿐만은 아닌 것 같습니다. 프란시스네 양 한 마리가 제 농장을 돌아다니는 걸 이번 주만 해도 세 번은 봤으니까요. 그 친구가 양 치는 걸 누가 좀 도와줘야겠다는 생각이 들었습니다.$B$B당신이 프란시스에게 가서 한번 알아봐 주시겠습니까? 이 불쌍한 어린 양도 함께 데려가 주십시오."},objectives={{51,941746452},"양치기 소년 프란시스에게 무법천지 양을 데려가야 합니다."}}
rows[29916]={completion={{65,149219856},"그들은… 멈추지 않겠지만, 적어도 우리는 반격했잖아요. 그렇죠?"},title={{34,317572500},"예리한 발톱과 군침 흘리는 턱"},description={"First the hawks came. You've probably seen some of them circling up above.$b$bThe wolves came shortly after. I think they smelled my weakness.$b$bI'm not nearly as brave as Master Shang thought I was. The master will be quite cross with me if I don't do something about these beasts.$b$bCan... can you help, $gsir:ma'am;?","처음에는 독수리들이 왔습니다. 하늘 위에 맴도는 독수리 몇 마리를 보셨을 겁니다.$B$B그 뒤 얼마 지나지 않아 늑대들이 왔습니다. 놈들은 제게서 나약함의 냄새를 맡은 것 같았지요.$B$B저는 샹 삼촌께서 생각하시는 것처럼 그다지 용감하지는 못합니다. 제가 이 야수들을 어떻게라도 하지 않으면 스승님께서 꽤 크게 화를 내실 겁니다.$B$B저 좀… 저 좀 도와주시지 않겠습니까?"},objectives={{50,1723907158},"도둑 초원매 5마리와 도둑 늑대 6마리를 처치해야 합니다."}}
rows[29917]={completion={{94,1649413293},"내가 그들을 막아내야 한다는 걸 알지만, 어쩌면 난 목동으로서의 자질이 없는 걸지도 몰라."},title={{7,1786316110},"루펠로"},description={{247,1016508469},"늑대들의 우두머리를 처치하면 나머지는 공격을 멈추지 않을까…?'라고 생각하고 있었습니다.$B$B우리는 놈을 루펠로라고 부릅니다. 강둑 반대편을 돌아다니고 있지요.$B$B<늑대들이 또 공격하자 프란시스가 안절부절합니다. 아무래도 당신 혼자 루펠로를 처치해야 할 것 같습니다.>"},objectives={{13,273814638},"루펠로를 처치해야 합니다."}}
rows[29918]={completion={{196,861376970},"프랜시스가 유능한 목자가 되기까지 예상보다 시간이 오래 걸렸습니다. 우리 모두 이런 단계를 거치죠... 제 아들 량도 한때는 약했습니다. 저도 마찬가지였고요. 하지만 그는 배우게 될 겁니다. 그것이 썬더풋 가문의 방식입니다."},progress={{44,1305301575},"당신은 두려움이 없어요. 당신의 마음속에서 그걸 느낄 수 있어요."},title={{19,1205746571},"용기란 이런 것이다!"},description={{457,35493597},"<프란시스에게 말하는 샹 썬더풋>$B$B프란시스, 용기를 내야 한다! 너는 두려움에 맞서는 용기만 없을 뿐, 훌륭한 양치기가 되기 위한 모든 것을 가지고 있단다!$B$B<당신을 바라보는 샹 썬더풋>이방인이여, 제 나머지 가족들을 도와주셨군요. 프란시스는 제게 둘째 아들이나 다름없습니다.$B$B저의 제자에게 두려움이 없다는 게 어떤 것인지 보여주십시오. 이 밧줄로 올가미를 만들어 저 위에 날아다니는 거대한 흰색 초원매들 중 한 마리를 잡아 처치해주십시오.$B$B<하늘을 가리킨 뒤 프란시스를 바라보고 자리를 떠나는 샹>"},objectives={{70,995873036},"목동의 올가미줄을 사용해 거대한 흰색 초원매를 잡아 처치해야 합니다."}}
rows[29919]={completion={{149,1201615193},"맥주 찾으신다면 잘 찾아오셨습니다, 이웃님. 아, 그리고 좀 지저분한 건 양해 부탁드립니다. 지난 며칠 동안 바이러스 때문에 좀 고생했거든요."},title={{23,1119606545},"위대한 자는 위대한 만큼 마신다"},description={"Hello again, $n. What is this, the fourth time we've run into one another already?$b$bSay... my keg is quickly becoming quite empty. I've heard mention of a brewery to the southwest, and that's where we're headed. Care to join us?","또 만났군, $N. 그러니까 이게… 벌써 네 번째인가?$B$B저… 내 맥주통이 벌써 바닥을 드러내고 있네.$B$B남서쪽에 양조장이 있다는 이야기를 듣고 그리로 향하는 길이었다네. 함께 가지 않겠나?"},objectives={{65,2090753562},"첸 스톰스타우트와 리 리를 남서쪽에 있는 양조장까지 호위해야 합니다."}}
rows[29920]={completion={{220,128279349},"그들이... 그들이 동의했다니?! 정말 환상적이야! 정말 고마워! 그들의 축복 덕분에 우리는 이 땅에서 가장 행복한 판다렌이 될 수 있어!$b$b이걸 받아줘. 판드리아크들에게 바치려고 했는데, 그들은 관심이 없어 보였거든."},title={{18,1995632897},"허락은 주먹을 타고"},description={{390,2120359740},"내 사랑, 로가 위대한 판다렌들께 저와 결혼해도 된다는 허락을 받으려고 했어요. 그 분들은 이미 돌아가셨지만, 우릴 응원해 주신다면 큰 힘이 될 거에요.$B$B그런데, 그 분들은 영혼이셔서, 우리가 준비한 선물이나 공물에 전혀 감동하지 않으시더라고요. 그 분들의 허락을 얻으려면, 로나 아니면 우릴 위해 싸우는 용사가 결투를 통해 그 분들에게 승리해야 해요.$B$B로는 착한 사람이지만 격투가는 아니에요.$B$B우릴 위해 용사가 되어 주시겠어요?"},objectives={{93,998750666},"위대한 판다렌 골든드래프트, 위대한 판다렌 윈드퍼, 위대한 판다렌 브램블스태프에게 도전하여 승리해야 합니다."}}
rows[29922]={completion={{450,1001827261},"당신의 행동으로 인해 오랫동안 잊고 있던 고대 예언에 대한 기억이 되살아났습니다. 이는 조사할 가치가 있습니다. 조사를 위해서는 옥이 필요합니다. 토야에게 가능한 한 많은 옥을 모아 당신에게 가져다주라고 지시했습니다. 옥을 가져오면 고대의 \"황제의 징조\"를 해독해 보겠습니다. 토야가 옥을 모으는 동안 자유롭게 마을을 둘러보세요. 이 마을 사람들은 당신과 같은 능력을 가진 사람을 필요로 할지도 모릅니다."},title={{19,487289687},"지혜를 찾아서"},description={{237,2078233235},"자리를 비우신 동안 전승지기 초 님이 너를 찾아왔었다.$B$B북쪽 새벽의 꽃 마을에 도움이 필요하다고 하시더군. 자세한 이유는 설명하지 않으셨다.$B$B연 장인 우트남에게 부탁해라. 아마 새벽의 꽃까지 널 기꺼이 데려다 줄 것이다."},objectives={{60,955389196},"연 장인 우트남과 대화하여 새벽의 꽃으로 가야 합니다."}}
rows[29923]={title={{14,1300018849},"꿈결 맥주"},description={{107,1809989785},"꿈결 맥주가 완성됐습니다.$B$B예언자의 돌에서 마셔보십시오. 붉은 탑 바로 오른쪽에 있습니다.$B$B구하십시오. 그러면 찾을 것입니다."},objectives={{65,1035687069},"예언자의 돌에서 꿈결 맥주를 마시고 하얀 졸을 찾아야 합니다."}}
rows[29924]={title={{14,1165686525},"케르 샨 사냥"},description={{224,1568897130},"케르 샨, 엄청 커다란 응가쟁이다.$B$B내 아들들 모두 꿀꺽했다! 이크 이크, 나브 나브, 이트 이트, 비티 비티… 나머지는 누군지 모르겠다.$B$B우낏 호젠 도와주나? 케르 샨 꿀꺽해라!$B$B그 응가쟁이 저기 있다.$B$B<동쪽을 가리키는 니비 니비>"},objectives={{31,1410330699},"호랑이의 숲에 있는 케르 샨을 처치해야 합니다."}}
rows[29925]={completion={{69,294640811},"토야가 날 위해 해낼 줄 알았어! 걔는 뭐든지 구할 수 있잖아."},progress={"Ah, hello again, $n! You received my message, then?","아, 다시 만나서 반갑습니다, $n님! 제 메시지 받으셨나요?"},title={{16,2142077929},"이게 전부라고요"},description={{173,579940248},"좋아요. 제가 구할 수 있는 건 모두 모았어요. 이게 남은 것 전부에요.$B$B초 님이 뭔가 중요한 일에 쓰셨으면 좋겠군요. 그 분을 만날 준비가 되면 말씀하세요. 타고 가실 것을 준비해 뒀어요."},objectives={{109,655597892},"황제의 전조에 있는 전승지기 초에게 긁어 모은 비취를 가져가야 합니다. 새벽의 꽃에 있는 토야와 대화하면 이동할 수 있습니다."}}
rows[29926]={completion={"Well I'll be... you actually did it!$B$BYou lookin' for a more permanent job, $gbuddy:sister;? I could use a bruiser like you around full-time!","세상에... 정말 해냈구나! 혹시 좀 더 안정적인 직장 찾고 있어, 친구? 너처럼 덩치 큰 사람이 정규직으로 필요하거든!"},title={{13,216379616},"재앙의 비취"},description={"You ever seen a shale spider, $c? Usually harmless, just creepin' around eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em \"nibblers.\"$B$BA few days back, we tunneled into a huge nest of these critters. They spilled out into the mines and went crazy, chewed up damn near everything in sight - including some of the boys.$B$BYou get in there and clear 'em out, and we got plenty of jade to spare. The quarry is directly west of here.","녹옥거미를 본 적이 있나요, $C님? 보통은 별로 해가 되는 일 없이 여기저기 기어다니면서 바위를 먹어치우지만, 사실 이놈들은 마치 사탕을 좋아하는 아이들처럼 비취를 좋아해요. 일꾼들은 ≪먹보≫라고도 부르죠.$B$B며칠 전에 굴을 파다가 커다란 녹옥거미 둥지를 건드렸어요. 그러자 거미들이 광산으로 쏟아져 나와 미친 듯이 활개를 치면서 눈에 띄는 것은 뭐든 먹어 치우고 있어요. 우리 일꾼들도 포함해서요.$B$B광산으로 가서 거미들을 없애주세요. 그러면 비취를 충분히 확보할 수 있어요. 채석장은 서쪽에 있고요."},objectives={{78,304421422},"녹옥 채석장에서 작은입 녹옥거미 12마리와 먹보 녹옥거미 6마리를 처치해야 합니다."}}
rows[29927]={completion={{122,731577879},"<하오가 잔해 속에서 몸을 일으키려 애쓰며 당신을 올려다봅니다.>$B$B아니, 아니. 됐어. 흐으으으!!$B$B음, 어쩌면 안 된 것 같아."},title={{10,221907082},"만의 남자"},description={{495,1708025778},"<처음으로 목소리를 낮추는 현장감독>$B$B이보세요, 이런 말씀 드리는 건 좀 그렇지만… 부탁할 게 하나 더 있어요. 바보같은 제 남편 하오가 지금 채석장에서 일하고 있어요. 아직 채석장으로 돌아가지 말라고, 너무 위험하다고 얘기했는데, 꼭 호젠처럼 고집이 센 데다 멍청하기는 호젠보다 더 하지 뭐에요. 일꾼들의 ≪사기를 북돋우려면≫ 자기가 꼭 필요하다고 하더라고요.$B$B내 사기는 어쩌고요?! 그 멍청이가 죽기라도 하면 전 어쩌냐고요!$B$B부디… 남편을 지켜봐 주세요. 돌아오라고 전해 주세요.$B$B<흐릿해진 눈으로 재빨리 고개를 돌리는 만>"},objectives={{41,396618202},"녹옥 채석장에서 하오 만을 찾아야 합니다."}}
rows[29928]={completion={"Catch? They were playin' CATCH with my product?!$B$BI hope you showed those walkin' toothpicks a thing or two.$B$BYou know, maybe you ain't a $gcub:tart; after all. I've been lookin' for some muscle to help out with my problem at the quarry.$B$BAnd judgin' by the size of the Lorewalker's restoration project here, I think you'll need a lot more jade.","캐치볼? 내 물건으로 캐치볼을 했다니?! 걸어다니는 이쑤시개 같은 놈들에게 제대로 한 방 먹였길 바라. 있잖아, 어쩌면 넌 생각만큼 속물적인 여자는 아닐지도 몰라. 채석장에서 내 문제를 해결해 줄 사람을 찾고 있었거든. 그리고 로어워커 복원 프로젝트 규모를 보니, 옥이 훨씬 더 많이 필요할 것 같군."},progress={{63,761609034},"<맨은 눈을 크게 뜨고 콧구멍을 벌렁거리며 당신을 기대에 찬 눈으로 바라봅니다.>"},title={{32,1008194178},"비취는 없고, 비명은 질러야 해요"},description={{366,21624432},"우리 비취 공급선이 모두 무너졌어요. 광산은 마치 죽음의 덫 같이 변했고, 담당자들의 사기는 사상 최악으로 떨어졌고, 이것만으로는 부족하다는 듯이 석공의 집에 나무 요마가 넘쳐나고 있어요!$B$B이제는 식물들까지 절 괴롭힌다니!$B$B비취가 그렇게 필요하다면, 남서쪽으로 향하는 길을 따라 내려가서 석공의 집으로 간 다음, 그 영광스런 젓가락들한테서 당신이 직접 뺐어오세요."},objectives={{85,307889368},"녹옥 석공의 집 주위에 있는 장난기 많은 요마에게서 비취 덩어리 15개를 회수해야 합니다."}}
rows[29929]={completion={{113,273586506},"<하오가 호탕하게 웃었다.>$B$BI가 봤어, 걔네들이 마치 케르 샨 왕이 직접 쫓아오는 것처럼 뛰쳐나오더라."},title={{8,503787318},"붙잡혔어요!"},description={{395,1935079065},"<온 힘을 다해 잔해 더미를 밀어내는 하오>$B$B흐으으으아아악!!$B$B맞춰볼까요? 우리 부인이 당신을 보냈지요? 우리 사랑스러운 꼬마 백합이 걱정이 많았겠군요. 하하! 내 일이라면 항상 그렇게 안절부절 못 한답니다. 보십시오. 흐으으아악!!! 동굴 붕괴 정도로는, 흐으으으아아악!!! 하오를 굴복시킬 수 없습니다.$B$B하지만 다른 일꾼들은 힘에 부치는 모양입니다. 가서 좀 도와주시겠습니까? 전 괜찮을 겁니다.$B$B정말이라니까요."},objectives={{50,1736539290},"녹옥 채석장에서 녹옥 광부 8명을 구출해야 합니다."}}
rows[29930]={completion={{72,1818842671},"해냈어! 내 꿀곰 인형을 돌려줬구나! 고마워, 고마워!"},title={{21,167286639},"비취를 그대 품 안에"},description={"Aw'right, so you need jade, do ya? I'd say we owe you at least that - we got plenty in the quarry, and thanks to yer help we should be back on schedule in no time.$B$BI should probably get back to the wife, so let's you and me take this cart o' the good stuff straight to her.$B$BNow, I ain't never met no $r t'were too big for me to pull in a wagon. You climb on the back there and let ol' Hao do the legwork.","좋아요, 타고 갈 것이 필요하다고 하셨나요? 그 정도는 해 드려야지요. 수레야 채석장 안에 수두룩하고, 당신 덕분에 일정을 맞출 수 있게 되었으니까요.$B$B저도 집사람에게 가봐야 할 것 같으니, 이 좋은 물건이 담긴 수레를 함께 타고 갑시다.$B$B제가 만나 본 $R 중에서 제가 끌지 못 할만큼 무거운 친구는 없었으니, 걱정 말고 수레에 타세요. 하오가 다리품 좀 팔아 보겠습니다."},objectives={{61,1388991489},"비취 수레를 타고 하오와 함께 황제의 전조에 가야 합니다."}}
rows[29931]={completion={{180,1606731720},"제가 제대로 보고 있는 건가요? 순수하고 품질 좋은 가공되지 않은 옥 한 상자 전체를 들여왔다고요? 정말 다행입니다. 포먼 맨이 우리를 위해 해 줄 거라고 믿었어요. 아, 그리고 당신도요. 가져다주셔서 감사합니다."},title={{19,802942290},"용의 심장"},description={{331,1080011313},"지금까지 정말 애 많이 쓰셨어요. 당신 덕분에 비취를 적당히 확보했어요. 이제 비취가 진짜 필요한 이에게 전해 줘야겠어요.$B$B제 친구 현장감독 레이케가 용의 심장에서 거대 조각상 세우는 일을 감독하고 있어요.$B$B여분의 비취를 한 짐 싣고, 그 친구에게 가져다 주세요. 옛 친구 만이 안부를 묻더라고도 꼭 전해주세요. 당신이 도착하기만을 애타게 기다리고 있을 거예요."},objectives={{65,1567644454},"비취 숲의 용의 심장에 있는 현장감독 레이케와 대화해야 합니다."}}
rows[29932]={completion={{343,2007987822},"뱀의 심장에서 소식을 가져오셨습니까? <노련한 현자는 옥광산과 거대한 옥 조각상에서 일어난 일에 대한 당신의 이야기를 인내심 있게 경청합니다.> <멀리까지 와주셔서 감사합니다, 낯선 이여. 하지만 지금은 옥뱀과 이야기할 수 없습니다. 그 고대의 존재는 매우 바쁘시고, 보시다시피 지금 여기에 안 계십니다.>"},title={{30,308142859},"옥룡사"},description={{369,1609450067},"여기서 지금까지 우리를 정말 많이 도와준 셈이야, 친구.$B$B이제 조각상을 완성할 만큼 비취를 충분히 모았고, 광산의 사건도 진정됐으니, 어서 옥룡 위론 님께 이 소식을 전해드려야겠어.$B$B사원에 도착하면, 옥룡사 입구에 계신 원로 현자 윈드이 님하고 이야기를 나눠봐.$B$B조금이라도 빨리 가고 싶으면, 가서 연 장인 쇼쿠에게 부탁하고. 아마 남는 연에 자네를 기꺼이 태워 줄 거야."},objectives={{140,813796040},"옥룡사의 입구 바깥에 있는 원로 현자 윈드이와 대화해야 합니다. 연 장인 쇼쿠와 대화하면 연을 타고 옥룡사로 날아갈 수 있습니다."}}
rows[29933]={completion={{31,1353975036},"우웩! 우웩! Wikket da Ook Dook!"},progress={{12,1357722067},"미끈미끈한 음식!"},title={{15,1883710363},"말벌 다리"},description={{212,2066123205},"너 정말 호젠 친구냐, 우낏? 어디 봐봐, 으음?$B$B그루끼끼 언덕 호젠, 이제 미끈고기 먹이 없다. 호랑말벌 다리는 잘린 뒤에도 물 속에서 꿈틀꿈틀 한다. 끝내주는 미끼야!$B$B보 보는 벌에 쏘여 아프다. 우낏이 가서 미끼 구하고 그루끼끼에 갖다 줘라."},objectives={{52,1987214860},"호랑이의 숲에 있는 호랑말벌에게서 벌레 다리 8개를 모아야 합니다."}}
rows[29934]={completion={{48,1095294294},"지금까지는 순조롭네요. 스파이 활동을 시작할 준비가 되셨나요?"},title={{13,2027764333},"라벤홀트 장원으로"},description={"If the egg is in Ravenholdt Manor, we can't risk torching it in an all-out assault. I'll need someone slippery to get in there and find out for sure.$B$BThat's you, $n.$B$BMostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!","만약 알이 라벤홀트 장원에 있다면, 본격적으로 쳐들어갔다간 알이 상하게 될지도 모릅니다. 누군가 몰래 숨어들어 가서 알을 확실히 찾아낼 사람이 필요합니다.$B$B바로 당신 말이지요, $N.$B$B모스트라즈가 그 장원에 침투하는 걸 도와줄 겁니다. 바깥에서 모스트라즈와 이야기하고, 함께 라벤홀트 장원으로 날아가세요. 행운을 빕니다!"},objectives={{81,215059991},"주홍빛 보루에 있는 모스트라즈와 대화해 함께 라벤홀트 장원으로 날아가야 합니다."}}
rows[29935]={completion={{75,289549812},"음... 착한 위켓이랑 싸우는 건가? 호젠도 못된 위켓이랑 싸우는 건가?"},title={{17,2006208234},"까라면 까야지"},description={{261,617117708},"흐으음… 우낏은 그렇게 나쁜 놈은 아닌 것 같다!$B$B다른 민둥머리는 호젠에게 친절하지 않았다.$B$B나쁜 우낏들이었던 모양이다!$B$B모든 우낏 전리품은 카 카에게 가져가야 한다. 족장의 명령이다!$B$B자, 우낏. 네가 가져가라. 카 카가 호젠의 새 친구 만나고 싶어한다.$B$B저기 남쪽에 있는 그루끼끼 언덕으로 가면 된다."},objectives={{54,62275460},"그루끼끼 언덕에 있는 족장 카 카에게 얼라이언스 명령서를 가져가야 합니다."}}
rows[29936]={completion={"Impressive work, $n.$B$BIt had not occurred to me that we might somehow befriend these creatures.$B$BWith their acceptance, we can now turn our attention to more important matters.","훌륭한 작품입니다, $n.$B$B우리가 어떻게든 이 생물들과 친해질 수 있을 거라고는 생각도 못 했어요.$B$B그들이 우리를 받아들였으니 이제 더 중요한 일에 집중할 수 있겠군요."},title={{17,1370912753},"희망은 불꽃을 타고"},description={{238,14385544},"잘 왔어, 우낏.$B$B난 카 카, 그루끼끼 언덕의 족장이다.$B$B두끼 우켐도 족장이 되고 싶어 했는데, 착한 우낏이 두들겨 팼다. 카 카에게 큰 선물이었다.$B$B호젠도 착한 우낏에게 선물 주겠다. 와장창 쿵쾅 추락한 땅에서 가져온 선물이다. 우낏에게 주려고 호젠이 잘 보관해 뒀다."},objectives={{74,1003185901},"그루끼끼 언덕에 있는 족장 카 카 근처에서 하늘 상어호 신호탄을 사용해야 합니다."}}
rows[29937]={completion={{52,1693680536},"그래! 바로 이거야. 두고 보면 알 거야..."},progress={{51,440471111},"너 그거 손으로 만진 거 아니지?"},title={{12,1198623691},"분노한 날짐승"},description={{305,880485901},"그래, 이 친구들이 생선을 좋아한다고 했지? 기왕 일이 이렇게 되었으니 말인데, 아예 호젠이 우릴 사랑하게 만들면 어떨까?$B$B추락한 비행선에서 가져온 폭약 가루가 좀 있으니, 이제 물고기들을 끌어모을 것만 마련하면 돼.$B$B그런 일에는 항상 내장이 최고더라고. 실패하는 법이 없어. 저기 남쪽에 새들이 좀 날아다니던데…$B$B응? 뭘 기다리고 있어?"},objectives={{68,895780707},"두끼끼의 땅에 있는 붉은발톱수리에게서 새 내장 한 줌 6개를 모아야 합니다."}}
rows[29938]={title={{16,678487508},"친구와 적"},description={{102,87867428},"나쁜 진위가 카 카의 조카들을 때렸다!$B$B우낏도 전에 호젠 많이 죽였다. 이제 우낏 너 진위 많이 없애라."},objectives={{46,356510518},"미끈고기 개울에서 진위 물가순찰병 7마리를 처치해야 합니다."}}
rows[29939]={completion={{101,1361855491},"우리는 이 얼간이들... 아니, 호젠들이 먹고사는 방식을 완전히 바꿔놓았습니다. 이제 그들은 예전과 같지 않을 겁니다!"},progress={{65,274173730},"다이너마이트로 해결할 수 없는 위기는 아직 겪어보지 못했습니다."},title={{9,2070539442},"미끼 폭탄"},description={{222,651973940},"자. 네가 가져온 새 내장으로 폭탄을 감쌌어.$B$B내장탄이라고 부를거야. 상표 등록 중이고.$B$B네가 이 녀석들하고 친구가 되었으니, 직접 가서 이 명예로운 일을 하는 게 어떨까?$B$B도화선에 불을 붙이고 물가에 던지기만 하면 돼!"},objectives={{64,171944424},"머키 둑에서 내장탄을 사용하고 폭발한 미끈고기 5개를 모아야 합니다."}}
rows[29940]={completion={{103,567405850},"완벽해. 앵은 멍든 순무와 물컹한 수박을 살펴본다. 저 아래에서 대체 뭘 하고 있었던 거야!?"},progress={{63,1750321411},"아버지가 채소를 드시고 싶어 하시면, 당신의 도움이 필요할 거예요."},title={{13,1065532382},"채소 되찾기"},description={{426,1950764930},"그래요, 맞습니다. 제가 다 알아서 하지는 못합니다. 아침 내내 토깽 놈들과 한바탕 해댔으니까요. 놈들이 제 채소에 손대지 못하게 하려고 온갖 발버둥을 쳐봤지만, 결국 조금 훔쳐가기는 했습니다.$B$B놈들은 훔쳐간 채소를 남쪽에 있는 강으로 가져갔습니다. 그걸로 뭘 하려는 건지는 모르겠지만, 먹는 것 같지는 않더군요.$B$B아버님께 지금 채소를 보내드려야 한다면, 놈들이 훔쳐간 걸 되찾아와야 하니 누군가가 좀 도와줘야 합니다. 당신이 저 좀 도와주시겠습니까?"},objectives={{49,2099998190},"도난당한 순무와 도난당한 수박을 각각 5개씩 획득해야 합니다."}}
rows[29941]={completion={"Good work $n.$B$BThe away team you assembled has departed.$B$BI hope Gorrok had the sense to change out of that ragged red shirt. I admire his patriotism, but he's had it on since we left Orgrimmar.$B$BThey won't be surprising anyone if he's wearing it...","잘했어, $n.$B$B네가 꾸린 원정팀이 출발했군.$B$B고록이 그 해진 빨간 셔츠를 갈아입었기를 바라. 그의 애국심은 존경하지만, 오그리마를 떠날 때부터 계속 저 셔츠만 입고 있잖아.$B$B그가 여전히 저 셔츠를 입고 있다고 해도 아무도 놀라지 않을 거야..."},title={{18,1719335000},"지평선 너머로"},description={"I recognize all you've managed to do here, $c. My report to the Warchief will include an account of your deeds.$b$bBut there's no time to rest!$b$bThis land must be charted and prepared for Horde settlement. I've already selected an away team to do just that.$b$bFind them before they grow comfortable here. Inform them of their mission, and try to convince your new friends to send along one of their own to serve as a guide.$b$bYou'll be staying here with me. We have preparations to make.","$C|1이여;여;, 지금까지 애써 준 것을 잘 알고 있소. 대족장님께 보고할 때도 당신의 공을 잊지 않고 전하겠소.$B$B하지만 아직 쉬고 있을 시간이 없소!$B$B어서 이 땅을 조사하고 호드 주둔지를 구축할 준비를 해야 하오. 적당한 파견 요원들을 이미 선발해 두었소.$B$B그들이 긴장을 풀기 전에, 어서 하나씩 만나 이야기를 나누시오. 각자에게 임무를 알려주고, 당신의 새 친구도 하나 함께 보내서 길잡이 역할을 시키시오.$B$B당신은 여기서 나와 함께 있어야 하오. 준비해야 할 것이 많으니까."},objectives={{70,1081516496},"쇼키아, 하사관 고로크, 그늘지배자 키린, 족장 카 카와 대화해야 합니다."}}
rows[29942]={completion={{104,1592750279},"이제 모두 배고파졌어! 이클 이클의 지혜는 정말 대단하군. 어쩌면 이클 이클은 언젠가 족장이 될지도 몰라..."},progress={{38,348167005},"위켓 그루크 걔네들 다 잡아먹었지?"},title={{36,655182536},"우낏 멍청이! 미끈고기는 호젠 거!"},description={{226,1519969655},"호젠이 미쳤다고 생각해, 우낏? 어디 호젠이 미끈고기 못 먹었을 때 다시 한번 만나 봐!$B$B호젠과 우낏이 같이 먹기에는 미끈고기 부족해.$B$B무쇠턱거북! 호젠은 우끼끼 무쇠턱거북 싫어해. 우낏 가서 무쇠턱거북 전부 잡아먹어라.$B$B<남쪽을 가리키는 이클 이클>"},objectives={{44,1223220030},"머키 둑에서 무쇠턱거북 스테이크를 4개 모아야 합니다."}}
rows[29943]={completion={{61,610720223},"그래! 스랄의 피 묻은 주먹에 맹세코, 얼라이언스 사냥이 너무 그리웠어!"},title={{23,1709855505},"적은 가까이에"},description={"Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on the Horde once again, $n.$b$bBut there's another side of this coin. We'd be naive to think the child was left alone.$b$bAny Alliance scum within sight of this land must be searching desperately for their precious princeling.$b$bYou and I are going to scour the area and root out his would-be rescuers.","안두인 린 왕자라니… 적 국왕의 아들이 아닌가! 운명의 여신이 다시 한번 호드에게 미소를 보내고 있소, $N.$B$B하지만 지금 우리가 쥔 동전의 이면도 봐야 하오. 이 아이가 혼자 남겨져 있었다고 생각할 수는 없다는 말이오.$B$B이 섬에 남은 얼라이언스 잔당은 모두 필사적으로 소중한 꼬마 왕자님을 찾고 있을 것이오.$B$B자네와 나, 우리 둘이 힘을 합쳐 주변을 수색하고, 왕자님의 구원자가 되기를 꿈꾸는 얼간이들을 모조리 소탕해야겠소."},objectives={{54,1775980036},"경치 좋은 전망대 근처에서 얼라이언스 침투요원 8명을 처치해야 합니다."}}
rows[29944]={completion={"<Chen nods.>$b$bGood work, $n. You're not bad in combat.$b$bWhat do you say we team up for the next part?","<첸이 고개를 끄덕인다.>$b$b잘했어, $n. 전투 실력이 나쁘지 않군.$b$b다음 편은 같이 할까?"},title={{22,252041818},"번식자들의 우두머리"},description={{354,1646563067},"내 맥주통 마개를 닫기 전에 할 일이 좀 있네. 이 토깽 놈들은 유랑도에 있는 것들과 전혀 다르지 않더군… 놈들과 비슷하게 생긴 토끼보다도 더 빠른 속도로 번식하는 단순한 말썽꾸러기였던 걸세.$B$B물론 한 놈도 빠짐없이 찾아내서 싹 없애버릴 수도 있지만, 무엇 때문에 그렇게 쓸데없이 피를 흘려야겠나? 그냥 놈들의 우두머리를 처치해버리게. 그러면 번식량이 서서히… 줄어들 걸세."},objectives={{60,1988289464},"프라이팬 지배자 아이위, 칼날발톱 진안야, 광포깡충이를 처치해야 합니다."}}
rows[29945]={completion={{295,1313230522},"어머나, 어머나, 어머나! 피를 가져왔다고? 빨간색을 가져오라고 하기 전에 주변을 좀 더 살펴봤어야 했나 봐. 으악! 리리는 재료 쪽으로 돌아서 꽃잎을 잠시 으깬 다음 피를 조금 섞는다. 그리고는 킥킥거리기 시작한다."},progress={{79,568987908},"페인트칠할 재료는 다 준비됐어? 난 미리 순무 좀 따왔어."},title={{26,1875649750},"노란색 더하기 빨간색은 주황색"},description={{350,1334749337},"첸 삼촌이 우리가 토깽 문제로 고생하는 머드머그 아저씨를 도와줄 거라고 하셨어요. 저는 좋아요! 얘네들이랑 장난치는 거 너무 재미있거든요.$B$B제 계획은 이래요. 순무를 주황색으로 칠한 다음에 토깽 놈들한테 당근이라고 속일 거예요.$B$B아주 재미있을 것 같아요.$B$B저는 순무를 모아올게요. $g아저씨:아줌마;는 식용으로 쓸 수 있는 주황색을 만들 게 있는지 찾아보세요."},objectives={{56,396522930},"초원 금잔화 10개와 동물 피의 약병 40개를 획득해야 합니다."}}
rows[29946]={completion={{179,1795977873},"그러면 적어도 몇 주 동안은 바이러스 걱정은 없을 겁니다. 머드머그가 방해받지 않고 맛있는 맥주를 몇 번 만들 수 있는 충분한 시간이죠. 그리고 그게 정말 중요한 거 아닌가요?"},title={{17,252490020},"굴어미"},description={{347,301819472},"수컷 우두머리를 해치웠으니 이제는 암컷 우두머리 차례군. 토깽들은 짝짓기를 할 때 상대를 아주 까다롭게 고르거나 그러지는 않지만, 그래도 아직 대부분은 암컷 우두머리가 존재하기는 한다네. 암컷 우두머리는 보통 덩치가 더 크고, 더 비열하며, 무리 중에서도 가장 거칠지.$B$B음… 그 암컷 우두머리에게 내 전투 기술을 한번 시험해보고 싶군. 옆에서 같이 싸워도 되겠나?"},objectives={{43,538609252},"추파를 처치해야 합니다."}}
rows[29947]={completion={{45,2011235075},"바하하하하! 난 바이러스 괴롭히는 거 너무 좋아."},title={{31,969714738},"당근 속에 순무"},description={{347,777339216},"첸 삼촌이 아직도 저를 감시하고 있어요. 그건 바로 제가 그동안은 마음대로 돌아다닐 수 없다는 뜻이죠. 저 대신 이 순무를 뒤틀린 소굴에 가져다 놓는 건 $g아저씨:아줌마; 손에 달렸어요. 제 말은… 아까 이야기했던 '주황색으로 칠한 당근' 말이예요.$B$B아주 간단하답니다. 이걸 토깽 앞에 던져놓고, 놈들이 이게 당근이라는 걸 알았을 때 어떻게 하는지 보기만 하면 돼요!"},objectives={{63,847601281},"토깽 저장꾼 12마리 앞에 주황색으로 색칠한 순무를 던져놔야 합니다."}}
rows[29948]={completion={"Aww, thank ya kindly, $gsir:ma'am;. You're a real $ggentleman:sweetheart;.","아, 정말 고마워요, $gsir:ma'am;. 당신은 정말 $ggentleman:sweetheart;."},progress={{45,259233695},"나는 그 바이러스 놈들에게 내 땅에 들어오지 말라고 경고했어."},title={{19,674804611},"날 때부터 도둑놈"},description={{384,529431839},"이렇게 토깽 문제를 도와주시다니 당신과 첸 님은 좋은 분이시군요. 저는 부탁하는 걸 좋아하는 성격은 아니지만, 다른 이가 도와준다는 것까지 싫어하지는 않습니다.$B$B밖에 나가서 저 토끼같이 생긴 놈들을 혼내주는 동안 홉 열매 자루도 있나 좀 찾아봐 주시겠습니까? 지난밤에 놈들이 훔쳐갔을 게 뻔하거든요.$B$B놈들 하는 꼬락서니를 봐서는 아마 훔쳐다가 베개로 썼을 겁니다."},objectives={{55,390388759},"뒤틀린 소굴에서 도난당한 홉 열매 자루 6개를 회수해야 합니다."}}
rows[29949]={completion={{147,686012196},"첸 삼촌이 돌아오실 거라는 걸 알아요. 걱정 안 해요. 사실, 이번이 드디어 판다리아를 탐험할 절호의 기회일지도 몰라요! 뚱뚱한 삼촌 때문에 발이 묶일 일도 없잖아요!"},title={{6,379559171},"맛볼 시간"},description={{82,1169823042},"보상을 받았다고 말하고 싶군. 머드머그가 만든 술을 맛보고 싶어 참을 수가 없네."},objectives={{42,895205497},"첸, 리 리, 그리고 머드머그와 함께 술을 마셔야 합니다."}}
rows[29950]={completion={{133,575226163},"정말 좋았어! 우리 다음에 또 탐험하러 가자. 그리고 첸 삼촌이 돌아오시기 전에 끝낸 것 같네. 완벽해."},title={{15,22857914},"리 리의 휴일"},description={{322,912336715},"첸 삼촌이 없을 때는 싸우지 말라고 하셨지만… 바깥세상을 탐험하지 말라고 하신 건 아니죠. 드디어 마흔일곱 발자국 걸을 때마다 멈춰 서서 다시 쉴 곳을 찾지 않고도 판다리아를 탐험해볼 기회가 온 거예요!$B$B저와 함께 가실래요? 여기서 그리 멀지 않은 곳에 아주 멋진 데가 많을 거예요."},objectives={{65,274047960},"리 리를 비단촌, 신 사이페라, 황지 폭포에 데려가야 합니다."}}
rows[29951]={completion={"You done good, $n. You done good.","잘했어, $n. 정말 잘했어."},progress={{48,626191443},"널 처음 본 순간부터 친구로 삼을 수 있겠다는 걸 알았어."},title={{11,41048085},"흙탕물"},description={{391,1621308689},"밖에 돌아다니는 동안 제 맥주 양조 과정에 도움이 될 만한 일도 해주셨으면 좋겠습니다. 사실 뭐 과정이라고 할 것도 없지만… 그냥 재료를 다 섞어 넣고 기다리기만 하면 되니까요.$B$B한번 들어보시기는 했을 텐데… 저는 남쪽 강둑에 있는 흙탕물을 써보고 싶습니다. 이 병에 그걸 담아서 제게 가져다주시겠습니까? 저는 홉 열매와 보리를 준비해 놓겠습니다."},objectives={{40,1882633227},"머드머그의 약병을 이용해 흙탕물을 모아야 합니다."}}
rows[29952]={completion={{43,1302416811},"어쩌면 난 애초에 정착할 운명이 아니었을지도 몰라."},title={{13,1931527401},"무너진 꿈"},description={{165,1743329478},"그렇네, 내가 스톰스타우트 양조장을 찾아냈다네… 생각했던 것만큼 환영받지는 못했지만…$B$B<술을 한 잔 들이켜는 첸>$B$B내 이야기 좀 들어보겠나?"},objectives={{51,677484854},"첸 스톰스타우트와 대화해 그의 이야기를 들어야 합니다."}}
rows[29966]={completion={"The Alliance must be purged from this land, $n!$B$BNo half-measures will do!","동맹은 이 땅에서 완전히 몰아내야 한다! 어중간한 조치는 용납될 수 없다!"},title={{22,1092986605},"초가삼간 불태우기"},description={"Look, $n!$b$bThese Alliance dogs built a camp up on the ridge.$b$bHere, take my grog. Let's make a fire they can see from Stormwind!$b$bFor the Horde!","이것 보시오, $N!$B$B저 위쪽 마루에 얼라이언스 강아지들이 야영지를 만들었소.$B$B여기, 내 그로그주를 받으시오. 그리고 가서 스톰윈드에서도 보일 만한 커다란 불난리를 쳐 보시오!$B$B호드를 위하여!"},objectives={{73,1418794165},"나즈그림의 그로그주를 사용하여 경치 좋은 전망대 꼭대기에 있는 얼라이언스 야영지를 불태워야 합니다."}}
rows[29967]={completion={{50,796445044},"공격을 격퇴했다는 말로는 부족할 정도입니다!"},title={{24,997443593},"파멸의 폭탄이 콰광!"},description={{321,868495692},"비상! 비상!$B$B네가 저 물고기 친구들을 처치했던 게 마치 벌집을 들쑤셔 놓은 것처럼 놈들을 자극했나 봐.$B$B녀석들이 그루끼끼 언덕에 대한 전면 공습을 시작했어!$B$B잠깐이나마 연구 개발에 시간을 투자하려 했는데, 내 메탄-수류탄 이론을 바로 상용화해야겠어!$B$B이 소굴 동쪽에서 만나자고. 수류탄 던질 준비를 하고 와!"},objectives={{92,1216111940},"그루끼끼 언덕 동쪽에 있는 리벳과 대화하고, 메탄 수류탄을 사용하여 진위의 공격을 막아내야 합니다."}}
rows[29968]={completion={{39,1765104386},"아, 발전의 냄새와 메탄가스 냄새가 나네."},progress={{42,894444018},"젖은 것들을 조심해야 해...휴!"},title={{16,541085078},"녹색 성장의 구린내"},description={"One word: Methane!$b$bWe're going green. Clean burning, high availability, all natural, and will keep the druids off my back when we get back to our neck of the world.$b$bThat, and I ran out of blasting powder...$b$bSo, I need your help, $n.$b$bNo, no, I wouldn't ask you to do the dirty work - especially not in front of the general. I'll collect these 'deposits' myself.$b$bYou gather up some wood for an outhouse - I'm thinking long-term here!","용건만 간단히 말할게. 메탄이 필요해!$B$B이제 저탄소 녹색 성장을 추구하겠어. 메탄은 타고 난 뒤에 남는 물질이 없고, 매장량도 풍부해. 게다가 본토로 돌아간 후에 드루이드들이 우릴 귀찮게 할 일도 없어!$B$B아, 물론 이제 화약이 다 떨어졌다는 점도 고려해야지…$B$B네 도움이 필요해, $N.$B$B아냐, 아냐, 너보고 더러운 일을 하라는 건 아냐. 메탄 '응집물'은 내가 직접 모을게.$B$B넌 뒷간을 세울 나무를 좀 가져와. 난 지금 장기적인 친환경 무기 사업을 생각하고 있다고!"},objectives={{46,643941849},"두끼끼의 땅에 있는 푸른 나뭇가지 7개를 모아야 합니다."}}
rows[29969]={title={{23,1667075966},"부서진 대지 수호자 조각상"},description={{159,1214513899},"심하게 손상된 이 조각상은 주인이 내다 버린 것 같습니다. 하지만 당신의 보석세공 기술과 적절한 재료를 사용하면 완벽하게 복원할 수 있습니다."},objectives={{58,709974977},"보석세공 기술과 적절한 재료로 부서진 조각상을 수리해야 합니다."}}
rows[29970]={title={{23,1667075966},"부서진 대지 수호자 조각상"},description={{159,1214513899},"심하게 손상된 이 조각상은 주인이 내다 버린 것 같습니다. 하지만 당신의 보석세공 기술과 적절한 재료를 사용하면 완벽하게 복원할 수 있습니다."},objectives={{58,709974977},"보석세공 기술과 적절한 재료로 부서진 조각상을 수리해야 합니다."}}
rows[29971]={completion={{22,1597889163},"문제가 생길 수도 있겠네요."},title={{17,1526301307},"정찰병의 귀환"},description={{126,1510814687},"이봐, 네가 바삐 돌아다니는 동안 정찰병들이 돌아왔어. 그것도 웬 얼라이언스 꼬마를 하나 데려왔다고.$B$B가서 이야기를 한 번 들어봐야 할 것 같은데."},objectives={{34,810905203},"그루끼끼 언덕에 있는 쇼키아와 대화해야 합니다."}}
rows[29981]={completion={"Lin asked you to help us out? Rather presumptive of her.$b$bStill, we are short-manned. We won't turn down your help... or the girl's. You have our thanks, $c.","린이 당신에게 도움을 요청했나요? 좀 주제넘은 부탁이시네요. 하지만 저희는 인력이 부족합니다. 당신의 도움이나 그 소녀의 도움을 거절할 수는 없죠. 감사드립니다."},title={{18,1167464603},"벌레 떼 소탕"},description={{428,197976994},"저는 이곳 출신이 아니에요. 오늘 말고는 이곳에 와본 적조차도 없죠. 하지만 이런 저라도 이곳에 뭔가 문제가 좀 있다고 말하고 싶어요.$B$B저기 있는 장벽은 판다렌의 땅으로 사마귀 놈들이 침입하는 것을 막으려고 지어졌어요. 이제 사마귀 놈들은 그 벽 위로 날개 달린 정찰병을 보내고 있답니다. 장벽 따위는 거기 있지도 않던 것처럼 말이죠!$B$B이 말라 비틀어진 놈들이 죽지 않는 이유는 바로 놈들이 병사가 아닌 농부를 공격하기 때문이에요. 당신 같은 강자와 싸운다면 아무런 힘도 못 쓸 텐데 말이죠."},objectives={{36,1852710058},"돌밭에서 이크티크 사마귀 14마리를 처치해야 합니다."}}
rows[29982]={completion={{142,476533047},"몇몇 고집 센 목장주들이 내 일을 더 힘들게 하려는 건가? (경비대장이 한숨을 쉬었다.) 좋아. 어떤 판다렌도 자기 땅을 지킬 권리를 빼앗지 않겠다."},title={{17,1665715871},"대피 명령"},description={{356,660769686},"밭에 농부 몇 명이 남아 있군요… 장벽이 무너지면 정말 위험한 곳에 있는 농부들도 있습니다. 저는 어떠한 농부라도 영웅인 척하는 것을 원하지 않습니다. 이 사마귀 떼는 우리가 손봐줄 것이며, 그렇게 하면 농부들은 집으로 다시 돌아갈 수 있을 겁니다.$B$B제 음영파 대원들은 대피 명령을 수행하려고 마을을 방어하느라 정신이 없습니다. 당신이 쓸모 있는 존재라는 것을 증명하고 싶습니까? 저 농부들을 위험에서 구출해주십시오."},objectives={{97,1640120614},"블랙소일 가족, 스페이드포우 가족, 그린틸 가족, 말퍼 가족을 대피시켜야 합니다."}}
rows[29983]={completion={{103,610552775},"훈련을 원하십니까?<판다렌은 몇 초 동안 아무 말 없이 당신의 체격을 살폈다.>좋습니다."},title={{17,519823330},"은둔 고수"},description={{267,1023191482},"지금부터는 우리가 돌밭을 수비할 수 있을 겁니다.$B$B<린 텐더포우를 가르키는 경비대 사령관 룬 마이>$B$B여기 있는 린은 ≪은둔 고수≫라고 불리는 자를 찾고 있습니다. 저는 그자가 누군지 압니다. 도움이 될 만한 걸 하나 말씀드리지요.$B$B북쪽으로 가십시오."},objectives={{56,2143519760},"네 바람의 계곡에서 사부 멍든손을 찾아야 합니다."}}
rows[29984]={completion={"You show promise, $n. We will continue.$b$bIt is now time for your first round of training.","$n, 당신은 가능성이 보입니다. 우리는 계속해서 노력할 것입니다.$b$b이제 첫 번째 훈련을 시작할 시간입니다."},title={{33,2088778402},"불굴의 주먹: 대나무 깨기"},description={{133,898406249},"일단 시험을 한 가지 해보겠네. 대나무 깨기지.$B$B자네 친구 린은 이 시험을 통과하지 못했다네.$B$B나를 따라오게나. 그리고 내 지시 사항을 잘 들어보게."},objectives={{90,149697965},"사부 멍든손과 대화한 뒤 대나무 더미 3개를 성공적으로 명중시켜야 합니다."}}
rows[29985]={completion={"You follow directions well, $n.","$n님, 지시사항을 잘 따르시네요."},title={{17,1539415834},"안개의 화신 처치"},description={{235,1257237865},"이 대나무숲의 안개는 정말이지 지긋지긋하게 성가시다네. 자네 같은 훈련생에게 이 일을 맡길 수 있게 돼서 이젠 나도 한숨 돌리겠군. 기이한 생명체들이 나무 사이의 안갯속에 도사리고 있다네. 놈들과 끊임없이 싸워서 몰아내야만 하지.$B$B이것도 수련의 일부라고 생각하게."},objectives={{26,671122393},"안개의 화신 12마리를 처치해야 합니다."}}
rows[29986]={completion={"You honor your people, $n.","당신은 당신의 백성을 존중합니다, $n."},title={{9,335233583},"안개 수호물"},description={{256,1996596663},"이것 보게, 훈련생$B$B내 집 근처의 숲에는 수호물 몇 개가 숨겨져 있다네. 안개를 흩뜨리는 효과가 좋긴 한데, 계속 관리를 해줘야 하지.$B$B여기서 북쪽과 서쪽, 그리고 남쪽에 하나씩 설치해 놨다네. 이것들을 찾아서 불을 밝혀주게나."},objectives={{77,1161664478},"북쪽 안개 수호물과 서쪽 안개 수호물, 그리고 남쪽 안개 수호물에 불을 붙여야 합니다."}}
rows[29987]={completion={"You have the gift of focus, $n. Not many of my students make it this far.$b$b<Master Bruised Paw glances over at Lin.>","$n, 자네는 집중력이 뛰어나구나. 내 제자들 중 이 정도까지 도달하는 학생은 많지 않아.$b$b<브루즈드 파우 사부는 린을 힐끗 쳐다본다.>"},title={{31,2128357535},"불굴의 주먹: 송판 깨기"},description={{99,521681371},"수련에 진전이 있는 것 같군. 나와 함께 가세나. 송판 깨기 시험에 도전해보게."},objectives={{91,1922834195},"사부 멍든손과 대화해 송판 더미 4개를 성공적으로 명중시켜야 합니다."}}
rows[29988]={completion={{81,1922167311},"이제 제가 왜 직접 달걀을 모으지 않는지 아시겠죠? 그럼 훈련을 계속해 볼까요?"},progress={{27,797555877},"부활절 달걀 찾기는 잘 진행되고 있나요?"},title={{16,1320745525},"맛좋은 알"},description={{373,2036903553},"불안해하는 건 알고 있지만, 아직 자네의 무예는 완성되지 않았네. 마지막 시험을 통과할 때까지는 계속 수련해야만 하네. 그래서 자네의 수련 목적으로… 알을 좀 가져왔으면 좋겠군.$B$B그래, 알 말이세. 동쪽 언덕 위에 있는 늪지대에 새 몇 마리가 살고 있다네. 보통은 다들 온순하지. 내가 몇 주 동안 먹을 수 있는 만큼의 알을 별문제 없이 수집해올 수 있을 걸세."},objectives={{82,98446191},"황제 제비갈매기 알 10개, 흰물고기잡이 학 알 4개, 코뿔새 타조 알 1개를 획득해야 합니다."}}
rows[29989]={completion={{177,1868905405},"<멍든 발 주인이 당신 앞에 절합니다.>$b$b돌이 당신의 주먹 아래 떨리고 부서집니다. 당신이 원한다면 산도 옮길 수 있는 힘이 있습니다.$b$b더 이상 제가 당신에게 가르칠 것은 없습니다."},title={{32,622688804},"불굴의 주먹: 석판 깨기"},description={"You have accomplished much in the short time you have been here, $n. I would not normally offer this test so soon... but I feel that you're ready.$b$bIt is time you attempted the Trial of Stone.","$N, 여기 머무는 동안 짧은 시간에 많은 것을 이뤄냈군. 이번 시험은 보통 이렇게 빨리 진행하지는 않는데… 하지만 자네가 준비됐다는 느낌이 드는군.$B$B이제 석판 깨기 시험에 도전해보게."},objectives={{90,396035684},"사부 멍든손과 대화한 뒤 석판 더미를 5개를 성곡적으로 명중시켜야 합니다."}}
rows[29990]={completion={{173,316053006},"린이 무사하다니 다행입니다. 우리 방어선은 현재까지는 잘 버티고 있습니다. 사마귀 무리가 계속해서 정찰병을 성벽 너머로 보내고 있지만, 그 이상은 별다른 성과를 거두지 못했습니다."},title={{23,714060057},"훈련과 규율"},description={"I told myself that, if I ever made it here to the Hidden Master, I would learn everything I could from him. This is my chance, $n. I'm not going to let it slip away.$b$bStill, I fear that Stoneplow needs us. I left early, before we were able to push the mantid scouts back. I'd feel better if you would check in with the Watch Commander for me.$b$bOh, and if you run into the others, maybe you should tell them where the Hidden Master is...","은둔 고수를 찾는 데 성공한다면 그분에게서 배울 수 있는 건 뭐든지 다 배우겠다고 저 자신에게 말했어요. 이건 제게 기회랍니다, $N 님. 그냥 놓치지만은 않겠어요.$B$B하지만 돌밭에 우리 도움이 필요할 것 같아 걱정이에요. 저는 사마귀 정찰병 놈들을 몰아내기 전에 떠나왔으니까요. 저 대신 경비대 사령관님을 좀 만나봐 주시면 제가 한숨 놓을 것 같아요.$B$B아, 그리고 다른 친구들을 만나면 은둔 고수가 어디에 있는지 말씀해주셔야 해요…"},objectives={{64,632493448},"네 바람의 계곡의 돌밭에 있는 경비대 사령관 룬 마이에게 보고해야 합니다."}}
rows[29992]={completion={{140,974772571},"린은 잠시 멈춰서 부어오른 발에 나뭇잎을 문질렀다. \"고마워! 나중에 제대로 된 연고를 만들 수 있지만, 지금은 이걸로 충분해.\""},progress={{11,1066731212},"아야! 아야! 아야!"},title={{43,567795963},"물주먹 린 텐더포우"},description={{445,1766450290},"샤오와 캉, 그리고 다른 친구들에게도 은둔 고수를 찾았다고 말해주고 싶은데, 이분은 저를 놓아주시질 않네요! 제게 먼저 대나무 깨기 시험을 통과해야 한다고 하셨답니다.$B$B<속삭이듯 말하는 린>그나저나 그 시험은 어떻게 통과하는 건가요?$B$B저는 바위에 정권을 수련하느라 당분간 여기 박혀 있어야 할 것 같아요. 그러다 보니 제 주먹이 우그러들기 일보 직전이네요.$B$B당신이 달비취 잎을 좀 모아다 주시면 이 고통을 조금이라도 가라앉힐 연고를 만들 수 있을 거예요."},objectives={{26,1538048500},"달비취 잎 18개를 모아야 합니다."}}
rows[29993]={completion={{180,1945008133},"당신은 가문의 야망에 눈먼 두 연인을 찾고 있습니다. 그들은 이곳에 있었지만, 자신들의 길을 지키려 애썼습니다. 슬프게도 그들은 나무들 사이에서도, 예술 속에서도 해답을 찾지 못했습니다."},title={{12,315268701},"소년을 찾아라"},description={{403,1698567566},"혹시… 내 아들 로를 보셨소? 조금 전까지도 여기 있었는데… 내가 오늘 떠날 거라고 이야기했었는데…$B$B아무래도 그 시라 골든드래프트라는 아이를 찾아간 것이 틀림 없소. 바로 그 아이 때문에 떠나야 하는 거요!$B$B내 아들이 골든드래프트 가문의 딸과 도망쳐버리는 꼴을 볼 수는 없지!$B$B나는 우선 이 주변에 둘이 없는지 찾아보겠소.$B$B전에는 둘이서 몰래 도원을 찾아가는 모습을 자주 봤었는데, 혹시 그쪽으로 가는 길이라면 그 아이들을 찾아봐 줄 수 있겠소?"},objectives={{25,1495583350},"잉크장인 웨이와 대화해야 합니다."}}
rows[29995]={completion={{68,1704262353},"어머, 낯선 분이시여! 제발 저희를 도와주실 수 있다고 말씀해 주세요. 그들이 제 아이를 정말 심하게 다치게 했어요."},title={{18,1650371688},"새벽의 제단"},description={{307,437166565},"당신이 찾는 ≪아이들≫은 사실 아이가 아니라 다 자란 판다렌입니다. 그 부모들이 뭐라고 주장하든. 둘의 사랑이 양 가문의 다툼 때문에 희생되어서는 안 됩니다.$B$B새벽의 제단에 가면 시라와 로를 찾을 수 잇을 겁니다. 둘 모두 집안의 가장 때문에 겪는 어려움에 대한 답을 찾고 있습니다."},objectives={{51,1364758807},"새벽의 제단에서 시라 골든드래프트를 찾아야 합니다."}}
rows[29997]={completion={"I am but an old jinyu, and those pesky water sprites were impossible to catch. Thank you, $n, for returning my staff to me.","저는 그저 늙은 진유일 뿐이고, 그 성가신 물의 요정들은 잡는 게 불가능했습니다. 지팡이를 돌려주셔서 감사합니다, $n 님."},progress={{87,1053924649},"연못물이 탁해졌어. 직원들이 마음을 진정시키고 물과 대화를 나눠야겠어."},title={{20,1164244487},"점술가의 딜레마"},description={{418,2131878837},"광산에서 우리를 도와줬다는 이야기를 듣고 나니 생각이 나는군. 혹시 여기 사원에서도 작은 문제를 하나 해결해 줄 수 있겠나?$B$B얼마 전, 현명한 마리가 사원에 다소 문제가 생겼다는 소식을 전해 왔네.$B$B물 요마들의 장난기가 심해져서, 이번에는 마리의 의식용 지팡이를 훔쳐 달아났다고 하더군.$B$B이번에도 우리를 도와줄 수 있다면 정말 고맙겠네. 물론 옥룡 님께도 자네의 활약상을 전해드리겠네.$B$B북쪽으로 난 길을 따라가 보게."},objectives={{47,633914705},"물 요마를 처치하고 현명한 마리의 지팡이를 되찾아야 합니다."}}
rows[29998]={completion={{63,379942017},"노성자 비주께서 당신을 보내셨다고요? 좋습니다. 저를 도와주십시오."},title={{24,1384389519},"사서의 곤경"},description={{278,671040127},"전승지기 스톤스텝 님께서는 이 사원 전체의 도서관을 책임지고 계시네. 하지만 요즘 무언가가 그 분을 괴롭히며 도무지 일을 하실 수 없게 만들었어.$B$B고대의 서적 수천 권을 옮겨 적어야 하는데, 지금 그 분이 다른 곳에 정신을 팔고 계시면 안 되네.$B$B남쪽 길을 따라 도서관으로 가서 그분이 무엇 때문에 고민하고 계신지 확인해 주겠나?"},objectives={{52,1669433393},"사원 도서관에서 전승지기 스톤스텝과 대화해야 합니다."}}
rows[29999]={completion={{98,646320222},"당신이 그들을 모두 찾아서 데려다주셨군요! 그들이 당신을 정말 좋아해요. 정말 감사합니다!"},title={{16,841185862},"기수의 교감"},description={{397,1658715653},"훈련장에 있는 어린 용들을 보셨나요?$B$B어린 용들은 장난기가 많아요. 그래서 훈련이 시작하기 전에 놀이를 하려고 도망쳐 버리는 일이 많죠.$B$B용들이 사라진 것을 아시면 스승님께서 화를 많이 내실 거예요.$B$B가서 걔들을 데려와 주실래요? 문제가 생기는 일이 없었으면 좋겠어요.$B$B널찍한 장소에서 놀기를 좋아하니까, 안마당과 첨탑 주변에서 찾아보세요."},objectives={{24,1930299308},"활발한 운룡 4마리를 찾아야 합니다."}}
rows[30000]={completion={{29,1564733263},"메시지를 전달하셨나요?"},title={{16,1721120154},"옥룡"},description={{146,1492559114},"옥룡 님께 말씀을 전하러 오셨죠?$B$B<고개를 들고 호기심에 가득한 눈으로 당신을 바라보는 소녀>$B$B이제 만나보실 시간이에요."},objectives={{27,398519674},"옥룡의 말을 들어야 합니다."}}
rows[30001]={completion={{66,1597395490},"네, 네, 감사합니다! 덕분에 그 수가 엄청나게 줄었어요."},title={{11,848180006},"나방은 책의 적"},description={{352,2061426870},"나방이 도서관에 침입했네. 나방!$B$B도서관장이라 말할 수 있는 이라면 누구나, 책벌레와 나방은 종이의 천적이라는 사실을 잘 알고 있지.$B$B이제 보니, 내 조수들은 모두 벌레를 무서워하더군. 도무지 쓸모 없는 겁쟁이들!$B$B제발, 당장 저 나방들을 없애주게! 판다렌 이야기꾼 수천 명이 남긴 작품의 운명이 자네 손에 달려 있네."},objectives={{21,772097899},"얼룩 나방 8마리를 처치해야 합니다."}}
rows[30002]={completion={{155,2008379643},"오, 정말 다행이에요! 큰 사고를 막아서 너무 안심이 돼요. 아니, 아니, 너무 가까이 오지 마세요. 신발에 아직 으깬 벌레 조각들이 붙어 있어요."},title={{16,1749316591},"역사의 한 장"},description={"The worst possible thing has happened, $r.$B$BWe. Have. Bookworms.$B$BThis is a critical situation. All bookworms in the library must be eradicated at once to prevent their spread.$B$BWe must squash this problem, literally! Please examine the infested books in the library and squash any bookworms that you find.","정말 끔찍한 일이 벌어졌네, $R.$B$B여기. 도서관에. 책벌레가. 나타났네.$B$B최악의 상황이야. 지금 당장, 다른 일을 모두 제쳐놓고라도 책벌레를 소탕해야 하네. 안 그랬다가는 숫자가 엄청나게 늘어나 버릴 거야!$B$B이 문제를 즉시 해결해 주게. 책벌레를 짓밟아 버리게! 도서관에서 벌레 먹은 책들을 살펴보고, 책벌레를 발견하면 당장 밟아 죽여버리게!"},objectives={{76,191596818},"도서관에서 벌레 먹은 책들을 살펴보고, 책벌레 12마리를 처치해야 합니다."}}
rows[30003]={title={{19,215172102},"수박 겉 핥기"}}
rows[30004]={completion={{155,412221257},"로어워커 스톤스텝이 다시 일을 시작했군요? 정말 놀랍습니다. 제가 보낸 지난 네 명의 사제들이 해내지 못한 일을 당신은 해냈군요. 두통이 사라지는 것 같습니다."},title={{23,2095849441},"모든 일이 해결되고"},description={"You have helped us more than you can ever imagine, $n.$B$BI do not know what I would do if our precious scrolls were ever to be lost.$B$BPlease return to the Elder Sage Rain-Zhu and tell him that the library is in order.","지금까지 자네가 상상하는 것 이상으로 내게 큰 도움을 주었네, $N.$B$B우리 소중한 두루마리들이 망가지기라도 했으면, 난 어떻게 했어야 할지… 상상도 할 수 없네.$B$B원로 현자 레인주에게 돌아가서, 도서관에 이제 아무 문제도 없다고 전해주게."},objectives={{78,1144233825},"비취 숲의 옥룡사에 있는 원로 현자 레인주와 대화해야 합니다."}}
rows[30005]={completion={"Yay! I saw the fireworks all the way from over here!$B$BThank you so much, $n.","야호! 여기서도 불꽃놀이가 보였어요! 정말 고마워요, $n."},title={{19,1714674084},"하늘을 밝히다"},description={"Do you like fireworks, $Gsir:miss;?$B$BI love them! In older times we would set them off to frighten away demons, but I just like them because they're pretty!$B$BI think there are still some old launchers lying around the temple.$B$BWould you go set off some big fireworks for me? It would make me so happy!","불꽃놀이를 좋아하시나요?$B$B전 정말로 좋아해요! 옛날에는 악마들을 쫓아버리려고 불꽃을 쏘아 올렸대요. 하지만 전 그냥 불꽃이 예뻐서 좋아해요!$B$B사원 주위에 옛날 발사대가 아직 남아 있는 것 같았어요.$B$B가서 커다란 폭죽을 쏴주실 수 있나요? 그럼 전 정말 행복할 거예요!"},objectives={{20,1272487738},"폭죽 8개를 발사해야 합니다."}}
rows[30006]={completion={"Thank you, $n. Every sha slain is another turn in the tide.","고마워요, $n. 샤를 한 마리 쓰러뜨릴 때마다 전세가 역전되는 거죠."},title={{22,240004511},"주위를 채운 어둠"},description={{272,35020776},"우리도 최선을 다했지만, 샤가 사원 주위의 봉인을 깨뜨렸네.$B$B여기서 놈들을 막아내지 못하면, 어둠이 비취 숲의 나머지 지역까지 번져나갈 걸세.$B$B지금 당장 자네의 도움이 필요하네. 눈에 띄는 샤는 모두 처치하게. 찾기가 어렵지는 않을 거야."},objectives={{21,1606092235},"샤 침략자 15마리를 처치해야 합니다."}}
rows[30007]={title={{39,910621801},"이벤트 추적: 도착 단계 완료"}}
rows[30009]={title={{22,23175959},"그루끼끼 소굴로 집합!"}}
rows[30011]={completion={{111,989465549},"정말 다행입니다! 점쟁이가 다시 명상에 전념하게 되었다는 소식을 듣고 큰 짐을 덜었습니다."},title={{12,618504463},"새로운 예언"},description={{70,815628916},"즉시 일을 시작하겠다고 원로 현자 레인주님께 전해주십시오."},objectives={{101,315110836},"비취 숲의 옥룡사 안마당에서 원로 현자 레인주와 대화해야 합니다."}}
rows[30015]={completion={{147,1579514389},"안녕하세요, $N님!$B$B던즈 블로섬에 오신 것을 환영합니다. 이곳은 저희 부족의 고향입니다.$B$B아쉽지만 떠나야겠습니다. 로어워커의 임무는 끝이 없으니까요.$B$B편히 쉬세요. 저희 부족은 당신처럼 재능 있는 분을 절실히 필요로 합니다."},title={{14,394861585},"새벽의 꽃"},description={{398,1789096817},"피와 번개의 축복을! 내 도끼가 굶주렸네!$B$B이 땅에서 얼라이언스 쥐새끼를 한 마리도 남기지 않고 말살하기 전까지는 오그리마로 돌아가지 않을 것이네.$B$B필요하다면 이 원주민들을 내가 직접 훈련시키지. 어떻게든 이 땅은 호드가 정착할 수 있는 곳이 될 걸세.$B$B그런데 저들의 우두머리가 이걸 자네에게 전해 주라고 하더군. 묘한 글자로 적힌 지도와 편지야.$B$B해야 할 일을 하게. 하지만 서두르는 게 좋을 것이네.$B$B전쟁의 기운이 무르익고 있으니…"},objectives={{99,1060000128},"새벽의 꽃에서 전승지기 초와 대화해야 합니다.$b$b그루끼끼 언덕에 있는 비행 조련사와 대화하면 날아갈 수 있습니다."}}
