rows[32105]={title={{24,1154599327},"온전한 기념물 장부"},description={{182,677444842},"유물이 매우 훌륭한 상태로 복원되었습니다. 전승지기와 고고학자들이 연구할 수 있도록 지식의 연단에 전시해도 될 것 같습니다."},objectives={{28,2097446809},"유물을 전시해야 합니다."}}
