rows[33222]={completion={{23,27621446},"너 부정행위 했지! 다 알아!"},title={{21,1335113315},"꼬마 토미 뉴커머"},description={{68,1557150350},"저도 전투용 애완동물이 있어요! 배틀하실래요? 재밌을 거예요, 정말이에요!"},objectives={{45,1162936391},"애완동물 대결에서 꼬마 토미 뉴커머를 물리치세요."}}
